(function(global){
'use strict';
const RA=global.RA=global.RA||{};const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('unbounded','Unbounded is formed from un- “not” + bound + -ed; bound in the sense “limited” is related to setting a boundary or limit.',[
C('unbounded.s1','规模','The archive faced an unbounded volume of requests after the discovery was announced worldwide.','这项发现向全世界公布后，档案馆收到的请求数量似乎没有上限。','unbounded growth/space/energy; seemingly unbounded','形容词，指规模极大、仿佛没有限制。','来自各地的请求持续增加，数量看似没有上限。'),C('unbounded.s2','规则限制','The artist enjoyed unbounded freedom to choose materials because the commission imposed no rules.','由于委托方没有设定规则，艺术家可以不受限制地选择材料。','unbounded freedom; unbounded by convention','形容词，指不受规则、职责或边界约束。','委托没有材料限制，艺术家拥有完全自由。')],M('The artist had unbounded freedom, but the contract strictly limited her to one approved material.','The artist had unbounded freedom because the contract placed no limits on her choice of materials.','strictly限制材料与unbounded freedom相矛盾。'),[Q(1,'What did the archive face after the announcement?','A seemingly limitless volume of requests','Exactly three requests','No requests at all','Sense 1 means very large and apparently without limit.','meaning'),Q(2,'Why could the artist choose any material?','No rules or restrictions were imposed.','A contract limited her to one material.','The archive refused her request.','Sense 2 is freedom not bounded by rules.','context'),Q(1,'Which phrase fits the size sense?','unbounded growth','unbounded by a strict contract','unbounded material limit of one','Unbounded can describe growth that seems to have no limit.','collocation'),Q(2,'In “unbounded freedom,” what is absent?','An outer restriction or rule','A choice of materials','The artist’s commission','The second sense means not limited by a boundary or duty.','meaning')]);
P('unbreakable','Unbreakable is formed from un- + break + -able; it describes something that cannot be broken or is extremely difficult to break.',C('unbreakable.s1','材料','The laboratory tested an unbreakable case by dropping it onto concrete from several heights.','实验室把一个坚固耐摔的箱子从不同高度落到水泥地上进行测试。','unbreakable glass/case; an unbreakable seal','形容词，表示物理上无法或极难打破，也可比喻难以摧毁。','箱子经受多次跌落仍完好。'),M('The unbreakable case split into pieces the first time it was touched gently.','The unbreakable case remained intact after repeated drops onto concrete.','轻触即碎与unbreakable所表达的坚固性直接相反。'),[Q(1,'What does unbreakable mean here?','Impossible or very difficult to break','Already broken into pieces','Easy to bend into a ring','The adjective describes strong resistance to breaking.','meaning'),Q(1,'How did the laboratory test the case?','By dropping it onto concrete','By dissolving it in water','By leaving it unopened','The example tests whether impact breaks the case.','context'),Q(1,'Which compound is natural?','unbreakable glass','unbreakable glass that shatters at a touch','unbreakable by breaking easily','The adjective commonly modifies a material or object.','collocation'),Q(1,'What does -able contribute in unbreakable?','The possibility of being broken, negated by un-','A plural ending','A past-tense marker','Breakable means capable of being broken; un- negates that quality.','word-formation')]);
P('unbridgeable','Unbridgeable is formed from un- + bridge + -able; it describes a gap or difference that cannot be crossed or reconciled.',C('unbridgeable.s1','意见分歧','After years of failed talks, the two parties still faced an unbridgeable gap over the language of the agreement.','多年谈判无果后，双方在协议措辞上仍存在无法弥合的分歧。','an unbridgeable gap/divide; seem unbridgeable','形容词，常比喻意见、理解或关系上的鸿沟无法跨越。','双方仍无法就关键措辞达成一致。'),M('The negotiators called the divide unbridgeable, then immediately settled every disputed point and signed the same text.','The negotiators called the divide unbridgeable because they could not settle the disputed wording.','立刻解决所有分歧并签署同一文本，说明鸿沟已经弥合。'),[Q(1,'What was unbridgeable between the parties?','A gap over the agreement’s wording','A small stream with a new bridge','A case that could be opened','Sense 1 is an impossible-to-cross difference or divide.','context'),Q(1,'An unbridgeable disagreement is…','Impossible to reconcile','Already settled by agreement','A disagreement about bridge paint only','The adjective often describes a deep difference in opinion.','meaning'),Q(1,'Which noun commonly follows unbridgeable?','gap','treadle','trophy','“An unbridgeable gap” is a common collocation.','collocation'),Q(1,'What does bridge contribute metaphorically?','The idea of connecting two sides','The idea of breaking glass','A measure of price','A bridge links separated sides; unbridgeable means they cannot be linked.','word-formation')]);
P('unbridled','Unbridled is formed from un- + bridle + -ed; a bridle controls a horse, so unbridled figuratively means not restrained or controlled.',C('unbridled.s1','情绪与行为','The announcement unleashed unbridled excitement among fans waiting outside the stadium.','这项公告让守候在体育场外的球迷兴奋不已，情绪毫无抑制。','unbridled enthusiasm/anger; unbridled ambition','形容词，指情绪、行为或力量不受约束。','球迷的热情没有受到克制。'),M('The speaker showed unbridled anger by remaining calm, measured, and entirely restrained.','The speaker showed unbridled anger by shouting and refusing to calm down.','完全冷静克制不符合unbridled anger的失控强烈之意。'),[Q(1,'What was the fans’ excitement like?','Unrestrained and intense','Quietly controlled','Impossible to understand','Unbridled means not restrained.','meaning'),Q(1,'What does bridle suggest in unbridled?','A restraint or control that is absent','A bridge across a river','A broken glass case','A bridle is used to control a horse; unbridled is figurative.','word-formation'),Q(1,'Which phrase is natural?','unbridled enthusiasm','unbridled enthusiasm carefully held in check','unbridled treaty of three pages','The adjective commonly describes strong emotion or ambition.','collocation'),Q(1,'Which behavior best shows unbridled excitement?','Fans shout and leap without holding back.','Fans sit quietly and show no reaction.','Fans leave before hearing the news.','Unbridled excitement is not held back.','context')]);
P('unbroken','Unbroken is formed from un- + the past participle broken; it means whole and undamaged, or continuing without interruption.',[
C('unbroken.s1','完整状态','The vase arrived in an unbroken condition after the courier packed it in foam.','快递员用泡沫包装后，花瓶完好无损地送到了。','unbroken seal/glass; remain unbroken','形容词，表示没有破裂、损坏或分割。','花瓶运输后仍完整。'),C('unbroken.s2','连续状态','The hiker walked for six hours without a break, keeping an unbroken pace along the ridge.','徒步者连续走了六个小时，沿山脊保持着没有中断的步伐。','an unbroken run/record/period; continue unbroken','形容词，表示持续而未被打断。','六小时的行走没有停顿。')],M('The glass arrived unbroken even though it was shattered into several pieces during delivery.','The glass arrived unbroken because it remained whole throughout delivery.','碎成数片意味着破裂，不能说unbroken。'),[Q(1,'What condition was the vase in?','Whole and undamaged','Cracked into several pieces','Uncertainly packed','Sense 1 means not broken.','context'),Q(2,'What did the hiker maintain for six hours?','An uninterrupted pace','A broken vase','A bridge over the ridge','Sense 2 means continuous without a pause.','meaning'),Q(1,'Which phrase refers to an intact object?','an unbroken seal','an unbroken seal split open','an unbroken silence lasting one second then stopping','Sense 1 describes something whole and undamaged.','meaning'),Q(2,'Which use means “without interruption”?','an unbroken record of daily practice','an unbroken plate that is whole','an unbroken case that cannot be opened','Sense 2 is continuity rather than physical condition.','distinction')]);
P('uncanny','Uncanny combines un- with canny, a Scots adjective meaning knowing or shrewd; it developed a sense of strange or mysterious, as if supernatural.',C('uncanny.s1','神秘感','The portrait’s eyes seemed to follow visitors around the room, creating an uncanny feeling.','画像的眼睛似乎随着参观者在房间里移动，让人感到诡异。','an uncanny resemblance/feeling; seem uncanny','形容词，表示奇异神秘，仿佛涉及超自然力量。','画像产生了不寻常、近乎超自然的感觉。'),M('The portrait seemed uncanny because it was completely ordinary and caused no strange or mysterious feeling.','The portrait seemed uncanny because its eyes appeared to follow visitors.','毫无奇异感与uncanny的神秘诡异之意相反。'),[Q(1,'Why did the portrait feel uncanny?','Its eyes seemed to follow people.','It was a plainly labeled landscape.','It had been uncarved from wood.','The strange effect creates a mysterious feeling.','context'),Q(1,'What does uncanny mean?','Strange and mysteriously unsettling','Common and completely familiar','Easy to break','The source sense suggests something supernatural or eerie.','meaning'),Q(1,'Which phrase is natural?','an uncanny resemblance','an uncanny very normal resemblance with nothing unusual','uncanny to a bridle','Uncanny commonly modifies a resemblance or feeling.','collocation'),Q(1,'Which adjective is closest to uncanny here?','eerie','undamaged','uncompetitive','The portrait creates an eerie, mysterious effect.','meaning')]);
P('uncarved','Uncarved is formed from un- + carve + -ed; it describes material left plain or in its natural state without being shaped by carving.',C('uncarved.s1','艺术材料','The sculptor displayed the uncarved block of cedar beside the finished statue.','雕塑家把未雕刻的雪松木块摆在完成的雕像旁边。','uncarved stone/wood; leave a block uncarved','形容词，表示尚未雕刻、仍保持朴素原状。','木块还没有被雕塑家加工。'),M('The museum labeled the uncarved statue because its face and every detail had been carefully carved.','The museum displayed an uncarved block before the artist shaped it into a statue.','已有精细雕刻的雕像不属于uncarved。'),[Q(1,'What was the uncarved block like?','It had not been shaped by carving.','It was a finished statue with detailed cuts.','It had been broken into pieces.','Uncarved means not carved.','context'),Q(1,'Which material could be described as uncarved?','A plain block of stone','A detailed wooden sculpture','A signed treaty','The adjective describes stone or wood left without carving.','meaning'),Q(1,'What does un- do in uncarved?','Negates the state of being carved','Makes the noun plural','Means “very”','The prefix un- means not or the opposite of.','word-formation'),Q(1,'Which phrase is natural?','an uncarved piece of marble','an uncarved statue with every detail finished','an uncarved carving already cut into shape','Uncarved marble has not yet been shaped.','collocation')]);
P('unceasing','Unceasing is formed from un- + cease + -ing; it describes something continuing without stopping or losing strength.',C('unceasing.s1','持续活动','Unceasing rain filled the reservoir through the night and continued into the morning.','连绵不断的雨水整夜注入水库，直到早晨仍未停止。','unceasing rain/effort; unceasing noise','形容词，指一直持续、不间断或不减弱的。','降雨跨越整夜并延续到早晨。'),M('The unceasing rain stopped after five minutes and did not return for the rest of the month.','The unceasing rain continued for hours without a pause.','仅持续五分钟后便停止不符合unceasing的持续义。'),[Q(1,'How did the rain continue?','Without stopping through the night','For only five minutes','At a single brief moment','Unceasing means continuing all the time.','context'),Q(1,'What does unceasing mean?','Never stopping or growing weaker','Already finished','Not yet confirmed','The word describes uninterrupted continuation.','meaning'),Q(1,'Which noun fits unceasing?','effort','a one-time pause','a broken vase','Unceasing can describe effort or activity that continues.','collocation'),Q(1,'What does cease mean in unceasing?','Stop','Begin','Carve','Un- negates cease: unceasing is not stopping.','word-formation')]);
P('uncertain','Uncertain is formed from un- + certain; certain came through Old French from Latin certus “settled, sure.” Uncertain means not sure, or not settled and therefore unreliable.',[
C('uncertain.s1','判断与事实','The witness was uncertain about the exact time because she had not checked the clock.','证人不确定准确时间，因为她没有看过钟。','uncertain whether/about; remain uncertain','形容词，表示对事实、决定或未来缺乏把握。','证人缺少核对时间的信息。'),C('uncertain.s2','不稳定状态','The schedule remains uncertain until the airline confirms whether the morning flight will operate.','在航空公司确认早班机是否运营前，行程安排仍不确定。','uncertain future/outcome; an uncertain supply','形容尚未确定、难以依赖或可能变化的状况。','航班是否运营尚未确认，所以行程可能变化。')],M('The flight schedule was uncertain even though the airline had issued a final confirmed time that could not change.','The flight schedule was certain after the airline issued a final confirmed time.','最终确认且不可更改的时间不再是不确定的。'),[Q(1,'Why was the witness uncertain about the time?','She had not checked the clock.','She had a written time confirmed by everyone.','She knew the exact minute.','Sense 1 is lack of confidence about a fact.','context'),Q(2,'Why did the schedule remain uncertain?','The airline had not confirmed whether the flight would operate.','The final schedule had been issued and could not change.','The flight had arrived on time.','Sense 2 describes a situation that is unsettled and unreliable.','meaning'),Q(1,'Which construction is grammatical?','uncertain about the result','uncertain of about the result','uncertainly the result about','Uncertain is commonly followed by about or whether.','grammar'),Q(2,'Which synonym fits an uncertain flight schedule?','unsettled','unchangeable','uncooked','The schedule has not been settled.','meaning')]);
P('uncertainly','Uncertainly is formed from uncertain + -ly; it means without confidence, assurance, or a clear outcome.',C('uncertainly.s1','表达方式','He answered uncertainly, pausing before each date because he was relying on memory alone.','他回答得犹豫不定，每说出一个日期前都停顿一下，因为只能依靠记忆。','speak/answer uncertainly; move uncertainly','副词修饰动作，表示缺乏信心或明确把握。','停顿和依靠记忆显示他不够确定。'),M('She spoke uncertainly with complete confidence and gave every answer instantly without hesitation.','She spoke uncertainly, hesitating as she tried to recall each date.','毫无迟疑且完全自信与uncertainly相矛盾。'),[Q(1,'How did he answer?','With hesitation and little confidence','Immediately and with certainty','In a three-part sequence','Uncertainly means without assurance or confidence.','context'),Q(1,'What does uncertainly modify in the example?','The verb answered','The noun date','The adjective memory','The adverb describes how he answered.','grammar'),Q(1,'Which word is the adverb?','uncertainly','uncertain','uncertainty','The -ly form is the adverb.','word-formation'),Q(1,'Which synonym best fits “answered uncertainly”?','hesitantly','confidently','unchangeably','Hesitantly captures the lack of confidence.','meaning')]);
P('uncertainty','Uncertainty is formed from uncertain + -ty and names either a state of not knowing or an unknown factor that may change a situation.',[
C('uncertainty.s1','缺少把握','The uncertainty about the storm’s path made the rescue team prepare boats for several possible routes.','风暴路径尚不确定，救援队因此为几条可能的路线准备了船只。','uncertainty about/over something; live with uncertainty','不可数名词，指缺少事实或情况易变所造成的不确定状态。','风暴路线未知，队伍不能确定唯一方案。'),C('uncertainty.s2','未知因素','One uncertainty in the budget is how much the bridge inspection will cost.','预算中的一个未知因素是桥梁检查需要花多少钱。','a major uncertainty; remove/reduce an uncertainty','可数用法，指一个尚未知晓、可能影响结果的因素。','检查费用尚不清楚，可能改变预算。')],M('The budget contained no uncertainty about inspection costs because the final invoice had already fixed the exact amount.','The budget contained an uncertainty about inspection costs because the inspection had not yet been priced.','已经确定的最终费用不是未知因素。'),[Q(1,'Why did the rescue team prepare several routes?','The storm’s path was uncertain.','The storm had already passed.','They were choosing a sculpture.','Sense 1 is a state of not knowing what will happen.','context'),Q(2,'What is one uncertainty in the budget?','The unknown cost of the inspection','A confirmed invoice amount','The color of a carved block','Sense 2 is a specific unknown factor.','meaning'),Q(1,'Which phrase is natural?','uncertainty about the storm’s path','uncertainty for the storm pathing','uncertainty of already confirmed','Uncertainty commonly takes about or over.','collocation'),Q(2,'How is the second use different?','It counts one unknown factor that may affect the result.','It is the adjective form.','It means a guarantee.','An uncertainty can be one particular unresolved factor.','distinction')]);
P('unchain','Unchain is formed from un- + chain; the verb means remove chains restraining someone or something, or free a person from a controlling restriction.',[
C('unchain.s1','实际解开','The rescue worker used a key to unchain the dog from the gate before moving it to safety.','救援人员用钥匙解开拴在门上的狗链，再把它带到安全处。','unchain a prisoner/animal; unchain from a post','及物动词，指解开锁链或使被链条拴住者脱身。','救援人员移除了把狗拴在门上的链条。'),C('unchain.s2','比喻解放','The new scholarship helped unchain students from the debt that had kept them from attending college.','新的奖学金帮助学生摆脱了阻碍他们上大学的债务束缚。','unchain someone from debt/fear; unchain creativity','比喻使人摆脱限制或束缚。','奖学金减轻债务，使学生能继续求学。')],M('The rescue worker unchained the dog by fastening a second heavy chain around its neck.','The rescue worker unchained the dog by removing the chain that held it to the gate.','再加一条链没有解开束缚；unchain 是移除链条。'),[Q(1,'What did the rescue worker do to the dog?','Removed the chain restraining it','Added another chain','Left it tied to the gate','Sense 1 is the literal act of removing chains.','context'),Q(2,'How did the scholarship unchain students?','It freed them from debt that blocked college attendance.','It physically tied them to a gate.','It made tuition more expensive.','Sense 2 means release from a figurative restriction.','meaning'),Q(1,'Which phrase is natural?','unchain the dog from the gate','unchain the gate under the dog','unchain to debt the student','Unchain can take the restrained person or animal as its object.','grammar'),Q(2,'What does unchain mean figuratively?','Free from a limiting burden','Make a limit permanent','Confirm an unknown fact','The figurative use means release from a restraint.','meaning')]);
P('unchangeable','Unchangeable is formed from un- + change + -able; it describes something fixed so that it cannot be altered.',C('unchangeable.s1','规则与事实','The constitution protects an unchangeable principle that cannot be removed by an ordinary vote.','宪法保护一项不能通过普通投票废除的固定原则。','unchangeable rule/fact; seem unchangeable','形容词，表示不可能或不允许改变的。','普通投票无法改变该原则。'),M('The rule was unchangeable, but any employee could rewrite it whenever they wished.','The rule was unchangeable, so employees could not rewrite it at will.','任何人都能随意修改说明规则并非unchangeable。'),[Q(1,'What does unchangeable mean?','Not capable of being altered','Likely to vary each day','Not yet decided','Un- negates changeable.','meaning'),Q(1,'Why was the principle unchangeable?','An ordinary vote could not remove it.','Every employee could rewrite it.','No principle had been adopted.','The constitution made it fixed.','context'),Q(1,'What does -able contribute in unchangeable?','Capable of being changed, negated by un-','An action in the past','A person who changes things','The suffix -able means capable of; un- reverses it.','word-formation'),Q(1,'Which phrase is natural?','an unchangeable principle','an unchangeable principle rewritten daily','an unchangeable change every hour','Unchangeable modifies something fixed.','collocation')]);
P('unchanging','Unchanging is formed from un- + change + -ing; it describes what remains the same, or a truth that holds without variation.',[
C('unchanging.s1','保持不变','The unchanging outline of the mountain helped hikers recognize the valley from every approach.','山脉始终不变的轮廓帮助徒步者从各个方向辨认山谷。','an unchanging pattern/landscape; remain unchanging','形容词，表示不发展、不变化或不呈现差异。','山的外形在不同观察位置依然一致。'),C('unchanging.s2','恒定原则','The manual states the unchanging rule that every sample must be labeled before storage.','手册规定了一条始终适用的规则：每份样本储存前都必须贴标签。','an unchanging truth/principle; unchanging rule','形容一直真实、始终适用而没有变化的原则。','该规则对每份样本都始终有效。')],M('The laboratory called its labeling rule unchanging, although it revised the rule differently every morning.','The laboratory called its labeling rule unchanging because it remained the same each day.','每天改动的规则不是unchanging。'),[Q(1,'What remained unchanging in the valley?','The mountain’s outline','The hikers’ route every hour','The weather forecast','Sense 1 means staying the same without variation.','context'),Q(2,'What kind of rule did the manual state?','One that continued to apply without variation','A rule changed every morning','An uncertain cost','Sense 2 describes a constant principle.','meaning'),Q(1,'Which phrase is natural?','an unchanging landscape','an unchanging landscape that changes every hour','an unchanging to landscape','Unchanging can modify a scene or pattern that stays the same.','collocation'),Q(2,'Which use is about a constant principle rather than a physical scene?','an unchanging rule','an unchanging mountain outline','an unchanging cloud shifting shape','Sense 2 can describe a truth or rule that always holds.','distinction')]);
P('uncharted','Uncharted is formed from un- + chart + -ed; it describes an area not yet shown on a map or investigated.',C('uncharted.s1','探索','The research vessel entered an uncharted inlet and recorded its depth before approaching the shore.','科研船驶入一处未绘入地图的海湾，在靠岸前测量了水深。','uncharted waters/territory; enter uncharted ground','形容词，表示尚未测绘或调查过的区域。','船员需要先测量未知水域再靠岸。'),M('The inlet was uncharted even though every bend and depth had been accurately mapped for centuries.','The inlet was uncharted because its bends and depths had not yet been surveyed.','已精确测绘的海湾不属于未绘制区域。'),[Q(1,'What is uncharted territory?','An area not yet mapped or investigated','An area shown on every current map','A place with unchangeable rules','The source sense is not mapped or explored.','meaning'),Q(1,'What did the research vessel do in the inlet?','Recorded its depth before approaching shore','Followed a centuries-old detailed map','Repaired an underground railway','The inlet had not yet been surveyed.','context'),Q(1,'Which phrase is idiomatic?','uncharted waters','uncharted waters mapped in every detail','uncharted into the map','Uncharted waters are areas not yet mapped or explored.','collocation'),Q(1,'What does chart mean in uncharted?','A map or mapped record','A chain','A meal that is uncooked','The compound refers to territory not shown on a chart.','word-formation')]);
P('uncle','Uncle came through Old French oncle from Latin avunculus “mother’s brother”; it names a parent’s brother or an aunt’s husband, and can be a child’s friendly address for a family friend.',[
C('uncle.s1','亲属关系','My uncle, my mother’s older brother, taught me how to repair a bicycle chain.','我的舅舅，也就是母亲的哥哥，教我修理自行车链条。','maternal/paternal uncle; uncle by marriage','可数名词，指父母的兄弟，或与姑姨结婚的男子。','句中说明他是母亲的兄弟。'),C('uncle.s2','亲切称呼','The children called their longtime neighbor “Uncle Ray” even though he was not related to them.','孩子们亲切地称相识多年的邻居为“雷叔叔”，尽管彼此没有亲属关系。','Uncle + name; call someone uncle','家庭中孩子也可用 uncle 亲切称呼家族朋友。','称呼表示熟悉和亲切，并非血缘关系。')],M('She called her father’s brother her uncle, but said he was not a relative because he was her parent’s sibling.','She called her father’s brother her uncle because he was her parent’s sibling.','父亲的兄弟正是 uncle，称其不是亲属与定义矛盾。'),[Q(1,'Who is an uncle in the family sense?','A parent’s brother or an aunt’s husband','A parent’s sister','A child’s classmate','Sense 1 names a male relative by birth or marriage.','meaning'),Q(2,'Why did the children call the neighbor “Uncle Ray”?','It was a friendly family-style form of address.','He was their mother’s brother.','He was a legal guardian in every case.','Sense 2 can be an affectionate address for a family friend.','context'),Q(1,'Which phrase is natural?','my maternal uncle','my maternal uncle who is my mother’s sister','my uncle’s brother as a female aunt','Maternal uncle means a mother’s brother.','collocation'),Q(2,'Does “Uncle Ray” always prove a blood relationship?','No, it can be a friendly form of address.','Yes, it always means a parent’s brother.','No, it means a court officer.','The second sense is an informal family-friend address.','distinction')]);
P('unclear','Unclear is formed from un- + clear; clear came from Old French cler and Latin clarus “bright, plain.” Unclear means hard to understand or not known or decided.',[
C('unclear.s1','表达','The instructions were unclear, so several volunteers assembled the filter with the valve facing the wrong way.','说明不清楚，因此几位志愿者把过滤器的阀门装反了。','unclear instructions/meaning; make something unclear','形容词，表示信息或表达不易理解。','错误安装说明读者无法清楚理解。'),C('unclear.s2','未知状态','It is still unclear whether the museum will reopen before the renovation is finished.','博物馆是否会在翻修结束前重新开放，目前仍不确定。','unclear whether/what; remain unclear','形容事实或决定尚未知晓。','是否提前开放还没有定论。')],M('The instructions were unclear, but every volunteer understood them immediately and assembled the filter correctly.','The instructions were unclear, so volunteers misunderstood how to position the valve.','所有人立即正确理解与说明不清楚的结果不相符。'),[Q(1,'Why did volunteers install the valve incorrectly?','The instructions were difficult to understand.','The instructions were perfectly clear.','The valve was unchangeable.','Sense 1 concerns a message that is not clear.','context'),Q(2,'What remains unclear about the museum?','Whether it will reopen before renovations end','The color of the already painted wall','The definition of a trestle','Sense 2 is an unresolved fact.','meaning'),Q(1,'Which phrase is grammatical?','unclear whether the museum will reopen','unclear that whether the museum reopen','unclear whether will the museum reopen','Unclear can introduce an indirect whether-clause.','grammar'),Q(2,'Which meaning is tested by “It is unclear whether…”?','The answer is not known or settled.','The message is hard to read.','The building is physically dark.','Sense 2 is uncertainty about a fact or decision.','distinction')]);
P('uncomfortable','Uncomfortable is formed from un- + comfortable; comfortable came through French from Latin confortare “strengthen, console.” It describes bodily discomfort or emotional unease.',[
C('uncomfortable.s1','身体感受','The stiff chair became uncomfortable during the three-hour lecture.','听了三个小时的讲座后，这把硬椅子坐起来很不舒服。','an uncomfortable chair/position; feel uncomfortable','形容词，表示身体疼痛或缺乏舒适感。','硬椅子长时间坐着引起身体不适。'),C('uncomfortable.s2','情绪体验','The question made the witness uncomfortable because it asked her to discuss a private conflict.','这个问题让证人感到尴尬，因为它要求她谈论私人冲突。','an uncomfortable question/silence; feel uncomfortable about','形容使人尴尬、担忧或略感害怕的情境。','私人话题使证人感到不自在。')],M('The stiff chair was uncomfortable, yet everyone sat on it for hours without any pain or lack of comfort.','The stiff chair was uncomfortable because it caused back pain during the long lecture.','没有痛感或不适与uncomfortable的身体义相矛盾。'),[Q(1,'Why was the chair uncomfortable?','Its stiffness caused physical discomfort.','It supported the listener perfectly.','It asked a private question.','Sense 1 is bodily discomfort.','context'),Q(2,'Why did the question make the witness uncomfortable?','It raised an embarrassing private conflict.','It was easy and unrelated to her.','The chair was too soft.','Sense 2 describes emotional unease.','meaning'),Q(1,'Which phrase naturally uses the physical sense?','an uncomfortable position','an uncomfortable answer that embarrasses a witness','an uncomfortable legal fact not yet decided','A position can make someone physically uncomfortable.','collocation'),Q(2,'Which reaction best shows emotional discomfort?','The witness hesitates before discussing a private conflict.','The witness sits on a soft chair.','The witness reads a clear timetable.','Hesitation about a personal topic reflects emotional unease.','context')]);
P('uncommon','Uncommon is formed from un- + common; common came through Old French from Latin communis “shared, ordinary.” Uncommon means not happening or found very often.',C('uncommon.s1','稀有情况','The botanist found an uncommon orchid growing on a shaded cliff far from the usual range.','植物学家在远离常见分布区的一处阴凉峭壁上发现了一种少见兰花。','uncommon species/event; relatively uncommon','形容词，表示不常见或不常发生。','该兰花远离通常分布区，出现频率低。'),M('The botanist called the orchid uncommon even though it grew in every garden and was seen daily by nearly everyone.','The botanist called the orchid uncommon because few people had seen it outside its usual range.','处处可见且每天都能遇到不符合uncommon。'),[Q(1,'What does uncommon mean?','Not found or happening very often','Shared by everyone every day','Impossible to change','The prefix un- negates common.','meaning'),Q(1,'Why was the orchid uncommon?','It was rarely found outside its usual range.','It grew in every garden.','It was a common houseplant.','The context says the species is unusual in that location.','context'),Q(1,'Which phrase is natural?','an uncommon species','an uncommon everyday object found everywhere','uncommon to be common daily','Uncommon commonly modifies events, species, or occurrences.','collocation'),Q(1,'Which word is closest in meaning?','rare','ordinary','unbroken','Uncommon means not common or relatively rare.','meaning')]);
P('uncompetitive','Uncompetitive is formed from un- + competitive; competitive is based on compete, from Latin competere “strive together.” Uncompetitive means not priced, skilled, or organized well enough to succeed against rivals.',C('uncompetitive.s1','市场竞争','The shop’s prices were uncompetitive, so customers bought the same tools from a cheaper supplier.','这家商店的价格缺乏竞争力，因此顾客从更便宜的供应商购买同样的工具。','uncompetitive prices/costs; remain uncompetitive','形容词，指价格、技能或组织水平不足以与对手竞争。','较高价格使商店失去顾客。'),M('The shop’s prices were uncompetitive, yet every customer chose it because its prices were lower than all rivals.','The shop’s prices were uncompetitive, so customers switched to lower-priced rivals.','顾客选择其更低的价格与“本店价格无竞争力”方向相反。'),[Q(1,'Why were the shop’s prices uncompetitive?','Customers could get the same tools more cheaply elsewhere.','The shop was the only place selling tools.','The prices were lower than every rival.','Uncompetitive means unable to succeed against rivals on price or other qualities.','context'),Q(1,'What can be uncompetitive?','Prices, skills, or organization','A fact that cannot be disputed','A chain used to restrain a dog','The source sense covers several aspects of competing.','meaning'),Q(1,'Which phrase is natural?','uncompetitive prices','uncompetitive prices lower than all competitors','uncompetitive to win every market','Prices that compare poorly with rivals may be called uncompetitive.','collocation'),Q(1,'What is the effect described in the example?','Customers switch to a rival supplier.','Customers buy more because the shop is cheapest.','The shop’s price becomes unchangeable.','The context shows loss of business to competitors.','context')]);
})(typeof window!=='undefined'?window:globalThis);

(function(global){
'use strict';
const RA=global.RA=global.RA||{};const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('uncomplicated','Uncomplicated is formed from un- + complicated; complicated came from Latin complicare “fold together,” describing something with many interwoven parts.',C('uncomplicated.s1','说明与过程','The guide gave uncomplicated directions for resetting the router in four clear steps.','指南用四个清楚的步骤给出了简单明了的路由器重置说明。','uncomplicated instructions/process; keep something uncomplicated','形容词，表示易懂、易处理而不复杂。','步骤少而清晰，读者可以直接操作。'),M('The guide called its instructions uncomplicated, but they required a specialist, twelve devices, and a hundred hidden steps.','The guide gave uncomplicated instructions that users could follow in four straightforward steps.','需要专家和大量隐含步骤不符合 uncomplicated 的简单易处理义。'),[Q(1,'What does uncomplicated mean?','Simple and not difficult to understand or manage','Full of interwoven steps','Still awaiting official confirmation','The word means not complicated.','meaning'),Q(1,'Why were the router directions uncomplicated?','They had four clear steps.','They required a specialist and a hundred hidden steps.','They could not be read.','The context gives a short, clear procedure.','context'),Q(1,'Which phrase is natural?','uncomplicated instructions','uncomplicated instructions with a hundred hidden stages','uncomplicated to the instructions','The adjective naturally modifies instructions or a process.','collocation'),Q(1,'What does un- contribute?','It negates the complexity in complicated.','It makes the noun plural.','It means “under.”','Uncomplicated is the negative form of complicated.','word-formation')]);
P('uncompromising','Uncompromising is formed from un- + compromise + -ing; it describes someone unwilling to weaken a principle or alter a position.',C('uncompromising.s1','立场','The judge took an uncompromising position on bribery and refused to excuse even a small payment.','法官对贿赂采取毫不妥协的立场，连小额付款也不肯开脱。','an uncompromising stance/attitude; uncompromising about standards','形容词，表示坚持原则、不愿让步。','法官不因金额小而改变反贿赂立场。'),M('The judge was uncompromising about bribery but excused every payment as soon as the accused asked.','The judge was uncompromising about bribery and applied the rule consistently.','一经请求便开脱与不妥协、坚持原则相反。'),[Q(1,'What was the judge’s uncompromising position?','Bribery could not be excused, even in small amounts.','Small bribes were acceptable.','The law should be ignored.','Uncompromising means unwilling to weaken a position.','context'),Q(1,'An uncompromising negotiator is…','unwilling to alter a firm principle','eager to abandon every standard','unable to understand instructions','The adjective describes firmness rather than concession.','meaning'),Q(1,'Which phrase is idiomatic?','an uncompromising stance','an uncompromising change of mind every minute','an uncompromising by the position','It commonly modifies stance, position, or attitude.','collocation'),Q(1,'What does the example show about the judge?','She applies the standard consistently.','She changes the rule for each person.','She has not heard of the rule.','Refusing exceptions illustrates an uncompromising stance.','meaning')]);
P('unconcerned','Unconcerned is formed from un- + concerned; it means not interested in or worried about something, or remaining calm in a tense situation.',[
C('unconcerned.s1','漠不关心','He seemed unconcerned about the deadline, although the rest of the team was still revising the report.','尽管团队其他人仍在修改报告，他似乎并不担心截止日期。','unconcerned about/with something; remain unconcerned','形容词，表示对他人在意的事不感兴趣或不担忧。','截止日期迫近但他没有表现出关心。'),C('unconcerned.s2','镇定','The pilot remained unconcerned during the brief turbulence and calmly followed the safety checklist.','短暂颠簸时，飞行员仍保持镇定，并冷静地执行安全清单。','appear/stay unconcerned; calm and unconcerned','形容词，表示在紧张情况下显得平静、不焦虑。','飞行员没有慌乱并继续按程序行动。')],M('The pilot was unconcerned during turbulence because she panicked, shouted, and abandoned the checklist.','The pilot stayed unconcerned during turbulence and calmly completed the checklist.','恐慌并放弃程序不是镇定的表现。'),[Q(1,'Why did the teammate seem unconcerned?','He showed no worry about the approaching deadline.','He was frantically revising the report.','He had not received a deadline.','Sense 1 means not worried or interested.','context'),Q(2,'How did the pilot remain unconcerned?','She stayed calm and followed the checklist.','She shouted and abandoned procedure.','She ignored the aircraft controls.','Sense 2 is calmness in a tense situation.','meaning'),Q(1,'Which preposition is natural?','unconcerned about the deadline','unconcerned the deadline with','unconcerned by about deadline','Unconcerned commonly takes about or with.','grammar'),Q(2,'Which word best matches the pilot’s manner?','composed','alarmed','uncooperative','She remains calm and in control.','meaning')]);
P('unconditional','Unconditional is formed from un- + conditional; condition came through Latin condicio “agreement, stipulation.” It means absolute, with no requirement attached.',C('unconditional.s1','协议与承诺','The grant was unconditional, so the clinic could spend it on any approved patient service without meeting extra targets.','这笔拨款没有附加条件，因此诊所可用于任何获批的患者服务，无须达到额外指标。','unconditional support/love/grant; offer something unconditionally','形容词，表示不附带条件、要求或限制。','拨款没有额外绩效要求。'),M('The grant was unconditional, but the clinic would receive it only if it met five new performance targets.','The grant was unconditional, so no additional performance targets were attached.','附带五项绩效条件就不是 unconditional。'),[Q(1,'What made the grant unconditional?','It had no extra targets or requirements.','It depended on five new performance targets.','It was not yet approved.','The adjective means absolute and not conditional on requirements.','context'),Q(1,'What does unconditional support mean?','Support offered without attached requirements','Support available only after a test','Support that changes every hour','There are no conditions attached.','meaning'),Q(1,'Which phrase is natural?','unconditional support','unconditional support only if targets are met','unconditional of support','The adjective commonly modifies support, love, or an offer.','collocation'),Q(1,'What is the opposite of unconditional?','conditional','uncomplicated','uncarved','Conditional support depends on specified requirements.','distinction')]);
P('unconfirmed','Unconfirmed is formed from un- + confirmed; confirm came from Latin confirmare “make firm.” It means not yet verified by evidence or not finally approved.',[
C('unconfirmed.s1','信息核实','The report described the cause of the outage as unconfirmed because technicians were still examining the damaged cable.','报告称停电原因尚未证实，因为技术人员仍在检查受损电缆。','unconfirmed report/sighting; remain unconfirmed','形容词，表示事实尚未由证据或正式报告证实。','调查尚未结束，因此原因没有确认。'),C('unconfirmed.s2','决定待定','Her place on the exchange program remained unconfirmed until the committee approved the final list.','在委员会批准最终名单之前，她的交换项目名额仍未最终确定。','unconfirmed booking/appointment; leave something unconfirmed','形容词，表示尚未最后决定、批准或接受。','名单尚未批准，所以名额仍待定。')],M('The outage cause was unconfirmed even though investigators had completed the report and officially verified it.','The outage cause remained unconfirmed because investigators had not finished checking the cable.','已正式核实与unconfirmed相反。'),[Q(1,'Why was the outage cause unconfirmed?','Technicians were still investigating it.','The final report had verified it.','The power had never gone out.','Sense 1 is a fact not yet supported by verification.','context'),Q(2,'When would her exchange place become confirmed?','After the committee approved the final list','Before anyone reviewed the list','When the cable was repaired','Sense 2 is an approval or decision still pending.','meaning'),Q(1,'Which phrase is natural?','an unconfirmed report','an unconfirmed report officially verified','an unconfirmed about report','The adjective commonly modifies a report or sighting.','collocation'),Q(2,'Which meaning applies to “unconfirmed place on the program”?','Not yet finally approved','Not yet discovered by investigators','Impossible to change','The place is pending final approval.','distinction')]);
P('unconformity','Unconformity combines un- + conformity; in geology it names a surface marking missing time between rock layers, where deposition stopped or older rock was eroded before newer layers formed.',C('unconformity.s1','地质学','The geologist traced an unconformity between the tilted older beds and the younger horizontal sandstone above them.','地质学家在倾斜的老岩层与上方较新的水平砂岩之间追踪到一个不整合面。','geological unconformity; angular unconformity','地质名词，指岩层记录中断、上下地层间存在时间缺失的界面。','倾斜老层与较新水平层相接，表示其间有沉积间断。'),M('The geologist called the contact an unconformity even though every layer formed continuously with no erosion or interruption.','The geologist identified an unconformity where erosion and a gap in deposition separated the rock layers.','连续沉积且无间断不符合地质学的 unconformity。'),[Q(1,'What does a geological unconformity mark?','A gap in deposition or erosion between rock layers','A continuously deposited layer with no time gap','A rule that cannot be changed','The term marks missing time in the geological record.','meaning'),Q(1,'Where did the geologist find the unconformity?','Between tilted older beds and younger horizontal sandstone','Inside a polished glass case','At the end of a confirmed contract','The differing layers meet across a depositional gap.','context'),Q(1,'Which word commonly modifies unconformity?','angular','uncompetitive','uncomfortable','Angular unconformity is a geological type.','collocation'),Q(1,'What does un- suggest in unconformity?','A lack of conformity or continuity','A threefold increase','A medical procedure','The geology sense involves a break in the sequence of layers.','word-formation')]);
P('unconquerable','Unconquerable is formed from un- + conquer + -able; conquer came through Old French from Latin conquirere “gain or acquire.” It means impossible to defeat or master.',C('unconquerable.s1','难以战胜','The fortress seemed unconquerable because its walls stood on a cliff and its stores could last through winter.','这座堡垒似乎坚不可摧，因为城墙建在悬崖上，储备足以支撑整个冬天。','an unconquerable fortress/spirit; seem unconquerable','形容词，表示无法征服、击败或掌握。','坚固位置与充足储备使堡垒难以攻克。'),M('The fortress was unconquerable, yet the first small attack captured it immediately without resistance.','The fortress seemed unconquerable because its location and supplies made it extremely difficult to capture.','轻易攻下且毫无抵抗与unconquerable相矛盾。'),[Q(1,'Why did the fortress seem unconquerable?','Its cliffside walls and winter supplies made capture difficult.','It had no walls or supplies.','It surrendered immediately.','Unconquerable means not able to be defeated or mastered.','context'),Q(1,'Which phrase uses the figurative sense?','an unconquerable spirit','an unconquerable map already drawn','an unconquerable meal left uncooked','The adjective can describe determination that cannot be overcome.','meaning'),Q(1,'What does -able mean in unconquerable?','Able to be conquered, negated by un-','Already conquered','A person who conquers','The suffix marks possibility; un- reverses it.','word-formation'),Q(1,'Which word is closest in meaning?','invincible','uncertain','uncomfortable','Invincible also means impossible to defeat.','meaning')]);
P('unconscious','Unconscious is formed from un- + conscious; conscious is based on Latin conscius “knowing, aware.” It means medically unresponsive, unaware of an action, or the hidden part of the mind.',[
C('unconscious.s1','医学','The cyclist was unconscious after the collision, so paramedics checked his breathing and called for an ambulance.','碰撞后骑车人失去意识，急救人员检查了他的呼吸并呼叫救护车。','fall/be unconscious; regain consciousness','形容词，表示因受伤、休克或疾病而暂时没有反应。','碰撞后他没有反应，需紧急救治。'),C('unconscious.s2','未意识到','She was unconscious of the camera behind the curtain and continued speaking naturally.','她没有意识到窗帘后有摄像机，仍然自然地继续讲话。','unconscious of something; be unaware','形容词，表示没有察觉某件事或自己做了某事。','她不知道自己正被拍摄。'),C('unconscious.s3','心理学','The therapist discussed how unconscious memories may influence a person’s reactions without entering awareness.','治疗师讨论了无意识记忆如何在不进入意识的情况下影响人的反应。','the unconscious mind; unconscious thought','名词性用法，指心理中隐藏的思想或记忆部分。','记忆影响反应但未进入当事人意识。')],M('The cyclist was unconscious after the collision, but he responded clearly to questions and described the crash.','The cyclist was unconscious after the collision and could not respond to questions.','能清楚回答问题说明没有处于失去意识状态。'),[Q(1,'What was the cyclist’s condition after the collision?','He was temporarily unable to respond.','He was fully alert and giving a report.','He was unaware of a camera only.','Sense 1 is a medical state of lost consciousness.','context'),Q(2,'Why did she keep speaking naturally?','She was unaware of the hidden camera.','She had fallen unconscious.','She was discussing unconscious memories.','Sense 2 means not realizing that something is happening.','meaning'),Q(3,'What did the therapist mean by unconscious memories?','Hidden memories that can affect reactions without awareness','Memories deliberately recalled every minute','A medical collision injury','Sense 3 is the hidden part of the mind.','meaning'),Q(1,'Which phrase means “not responding after injury”?','be unconscious','be uncertain about','be uncompetitive','The medical use describes temporary unresponsiveness.','distinction')]);
P('unconsciously','Unconsciously is formed from unconscious + -ly; it means in a way that is not conscious, deliberate, or fully noticed.',C('unconsciously.s1','无意识行为','He unconsciously tapped the table while reading, only noticing the movement when his colleague pointed it out.','他读书时无意识地敲着桌子，直到同事指出才注意到这个动作。','act/smile/unconsciously; unconsciously repeat a habit','副词，表示行为并非有意识或刻意进行。','他没有察觉自己在敲桌子。'),M('She unconsciously planned every movement in advance and carefully chose each tap to send a message.','She unconsciously tapped the table without noticing she was doing it.','刻意计划并传递信息说明动作是有意识的。'),[Q(1,'How did he tap the table?','Without consciously noticing the movement','As a carefully planned signal','After receiving formal instructions','Unconsciously means not deliberately or consciously.','context'),Q(1,'What did his colleague do?','Pointed out the movement he had not noticed','Asked him to write a treaty','Removed a chain from the table','The colleague made him aware of the habit.','meaning'),Q(1,'Which form is the adverb?','unconsciously','unconscious','unconsciousness','Adding -ly forms the adverb.','word-formation'),Q(1,'Which word is closest in meaning?','involuntarily','deliberately','uncompetitively','The action happens without conscious intention.','meaning')]);
P('unconsolidated','Unconsolidated is formed from un- + consolidated; consolidate comes from Latin consolidare “make firm.” It describes material not hardened or accounts not merged.',[
C('unconsolidated.s1','地质材料','The geologist sampled unconsolidated sand that shifted easily when water flowed through it.','地质学家采集了未固结的砂土，水流通过时砂粒很容易移动。','unconsolidated sediment/soil; loose unconsolidated material','形容词，指沉积物尚未压实或胶结成坚硬岩石。','砂粒松散且容易被水移动。'),C('unconsolidated.s1','财务记录','The auditor kept the subsidiary’s accounts unconsolidated until the ownership review was complete.','审计员在所有权审查完成前，没有把子公司的账目合并。','unconsolidated accounts/financial statements','形容账目或实体尚未合并到一个整体中。','子公司账目在审查结束前仍分别记录。')],M('The sand was unconsolidated because it had been compressed and cemented into solid rock.','The sand was unconsolidated because its loose grains had not been cemented together.','已胶结成坚硬岩石的材料不是unconsolidated。'),[Q(1,'What was the unconsolidated sand like?','Loose and easily shifted','Cemented into hard rock','Merged into one company account','Sense 1 is material not hardened or compacted.','context'),Q(1,'Why were the subsidiary accounts unconsolidated?','They had not yet been merged.','They had been physically turned into sand.','The ownership review was complete.','The source sense covers separate accounts not yet consolidated.','meaning'),Q(1,'Which phrase is common in geology?','unconsolidated sediment','unconsolidated solid granite cemented into rock','unconsolidated court verdict','Loose sediment may be described as unconsolidated.','collocation'),Q(1,'Which meaning is used in “unconsolidated accounts”?','Not merged into a single financial statement','Not hardened into stone','Not consciously noticed','The same adjective also applies to accounts that remain separate.','distinction')]);
P('unconstitutional','Unconstitutional is formed from un- + constitutional; constitution comes from Latin constituere “set up, establish.” It describes something contrary to the rules or principles of a constitution.',C('unconstitutional.s1','法律与政府','The court ruled the search unconstitutional because officials had entered the home without the warrant required by law.','法院裁定这次搜查违宪，因为官员未取得法律要求的搜查令便进入住宅。','unconstitutional law/search; declare something unconstitutional','形容词，表示违反宪法或宪法原则。','缺少宪法要求的授权使搜查违反规则。'),M('The court called the search unconstitutional even though it fully followed the constitutional warrant procedure.','The court called the search unconstitutional because officials entered without the required warrant.','完全遵循宪法程序的行为不能仅因此被称为违宪。'),[Q(1,'Why did the court rule the search unconstitutional?','Officials entered without the required warrant.','They followed every required constitutional procedure.','The house was uncarved.','The decision was based on a constitutional rule.','context'),Q(1,'What does unconstitutional mean?','Contrary to a constitution or its principles','Not yet confirmed by evidence','Not likely to compete','The adjective describes a violation of constitutional rules.','meaning'),Q(1,'Which verb commonly goes with unconstitutional?','declare a law unconstitutional','unchain a law unconstitutional','tread a law unconstitutional','Courts may declare a law or action unconstitutional.','collocation'),Q(1,'What is the role of un- here?','It marks opposition to constitutional rules.','It means below the constitution.','It marks a past event.','Unconstitutional is the negative form of constitutional.','word-formation')]);
P('uncontested','Uncontested is formed from un- + contested; contest comes from Latin contestari “call to witness, dispute.” It means accepted without challenge or won when no one else competes.',[
C('uncontested.s1','事实认定','The report treated the date of the bridge closure as uncontested because every witness gave the same record.','报告认为桥梁封闭日期没有争议，因为所有证人都提供了相同记录。','an uncontested fact/claim; remain uncontested','形容词，指没有人提出质疑或反驳。','证人记录一致，没有人争议该日期。'),C('uncontested.s1','竞赛','Mira won the club election uncontested after the other candidates withdrew before the deadline.','其他候选人在截止日期前退出后，米拉在没有对手的情况下赢得了俱乐部选举。','win uncontested; an uncontested seat/election','形容词，指竞选或比赛中没有其他参赛者挑战。','其他候选人退出，她没有竞争对手。')],M('The election was uncontested even though four opponents campaigned against Mira and challenged every result.','Mira won uncontested after all other candidates withdrew.','有多名对手竞选并挑战结果，说明竞争并非没有人挑战。'),[Q(1,'Why was the bridge closure date uncontested?','All witnesses gave the same record.','Witnesses supplied conflicting dates.','The date had never been recorded.','The one source sense covers both accepted facts and elections without rivals.','context'),Q(1,'How did Mira win uncontested?','Other candidates withdrew and no one opposed her.','Four opponents ran against her.','The election was cancelled.','The same sense also describes a contest won without opposition.','meaning'),Q(1,'Which phrase is natural?','an uncontested fact','an uncontested fact challenged by everyone','an uncontested of the date','Uncontested can modify facts or claims not disputed.','collocation'),Q(1,'What does uncontested mean in an election?','No rival candidate competes.','Every candidate challenges the result.','The result is not yet counted.','The election sense is included in the single source sense.','distinction')]);
P('uncontrollably','Uncontrollably is formed from un- + controllably; control came through French from Latin contra rotulum, “against a roll/register,” and developed the sense of directing or restraining. It means without the ability to stop or restrain an action.',C('uncontrollably.s1','动作与情绪','The child laughed uncontrollably when the puppet slipped off the table and landed in a bowl of flour.','木偶从桌上滑落、掉进面粉盆时，孩子笑得停不下来。','laugh/cry/shake uncontrollably','副词修饰动作，表示无法自行停止或控制。','孩子无法控制自己的笑声。'),M('He laughed uncontrollably but stopped his laughter instantly whenever anyone asked him to.','He laughed uncontrollably and could not stop even when he tried.','能随时按要求停止说明他仍能控制笑声。'),[Q(1,'How did the child laugh?','So intensely that he could not stop','Quietly and under complete control','Only after the performance ended','Uncontrollably means without the power to restrain the action.','context'),Q(1,'Which action can be done uncontrollably?','cry','confirm a date','uncarve a stone without moving','The adverb often modifies strong bodily or emotional actions.','collocation'),Q(1,'What does -ly do in uncontrollably?','Forms an adverb describing how an action happens','Forms the plural','Turns the word into a noun','Uncontrollably modifies a verb such as laugh.','word-formation'),Q(1,'Which phrase is closest in meaning?','without being able to stop','with deliberate restraint','without uncertainty','The word describes loss of control.','meaning')]);
P('uncontrolled','Uncontrolled is formed from un- + controlled; it describes growth or spread not kept within limits, or feelings and actions shown without restraint.',[
C('uncontrolled.s1','增长与传播','Uncontrolled runoff carried soil into the lake after the construction site was left bare.','施工场地裸露后，未受控制的径流把泥土冲进了湖里。','uncontrolled growth/spread/runoff; remain uncontrolled','形容词，指没有得到限制、管理或抑制。','没有覆盖的场地让径流自由带走土壤。'),C('uncontrolled.s2','情绪行为','His uncontrolled anger frightened the staff when he began shouting across the office.','他在办公室里大声吼叫，无法控制的愤怒吓到了员工。','uncontrolled anger/laughter; uncontrolled behavior','形容词，指情绪、言语或行为缺乏自我克制。','喊叫行为显示他没有克制愤怒。')],M('The site had uncontrolled runoff, but every drop of water was captured in a sealed drain and could not carry soil away.','The site had uncontrolled runoff that flowed over bare ground and carried soil into the lake.','完全收集并控制的水流不是uncontrolled runoff。'),[Q(1,'What did uncontrolled runoff do?','Carried soil from the bare site into the lake','Stayed inside a sealed drain','Stopped before leaving the site','Sense 1 is flow not kept within limits.','context'),Q(2,'What made the staff afraid?','His unrestrained anger and shouting','A clear instruction manual','An unchangeable principle','Sense 2 describes emotion or behavior without restraint.','meaning'),Q(1,'Which phrase is natural for environmental management?','uncontrolled runoff','uncontrolled runoff captured completely in a sealed drain','uncontrolled according to the plan','Uncontrolled can describe runoff that is not managed.','collocation'),Q(2,'Which behavior is uncontrolled?','Shouting in anger without restraint','Speaking calmly after taking a breath','Following a safety checklist','Sense 2 concerns lack of restraint in behavior.','distinction')]);
P('unconventional','Unconventional is formed from un- + conventional; convention comes from Latin conventio “agreement or assembly.” It means not following usual accepted methods or, of a person, living outside ordinary social rules.',[
C('unconventional.s1','方法','The engineer proposed an unconventional cooling system that used shaded water channels instead of compressors.','工程师提出了一种不同寻常的冷却系统，用遮阴水渠取代压缩机。','unconventional method/solution; take an unconventional approach','形容词，表示不按通常方式或公认方法行事。','水渠冷却与常见压缩机制冷方案不同。'),C('unconventional.s2','生活方式','The artist lived an unconventional life, moving between studios and refusing a fixed daily schedule.','这位艺术家过着不拘常规的生活，在工作室间迁居，也不设固定日程。','an unconventional lifestyle/person; unconventional habits','也可形容生活或行为较自由，打破社会常规。','生活安排不遵循固定的社会日常模式。')],M('The engineer’s proposal was unconventional because it copied the standard compressor design in every detail.','The engineer’s proposal was unconventional because it replaced the standard compressor with water channels.','完全照搬标准方案不属于unconventional。'),[Q(1,'Why was the cooling system unconventional?','It replaced compressors with shaded water channels.','It copied the standard compressor system exactly.','It used no cooling at all.','Sense 1 is a departure from usual methods.','context'),Q(2,'What describes the artist’s lifestyle?','It did not follow a fixed conventional routine.','It strictly followed an ordinary daily schedule.','It was not yet confirmed.','Sense 2 can describe a free way of living outside social convention.','meaning'),Q(1,'Which phrase is natural?','an unconventional solution','an unconventional solution identical to the standard one','unconventional to the method','The word commonly modifies a method, solution, or approach.','collocation'),Q(2,'Which use is about a person rather than a method?','an unconventional lifestyle','an unconventional cooling system','an unconventional technical approach','The second sense describes how a person lives or behaves.','distinction')]);
P('unconvinced','Unconvinced is formed from un- + convinced; convince comes from Latin convincere “overcome, prove.” It means not persuaded that a claim is true or doubtful that something will succeed.',[
C('unconvinced.s1','论证','The committee remained unconvinced by the forecast because it did not explain how the figures were calculated.','委员会仍未被这份预测说服，因为报告没有解释数字的计算方法。','remain/be unconvinced by; unconvinced that','形容词，表示尚未相信某项论证或解释。','缺少计算依据使委员会无法接受预测。'),C('unconvinced.s2','对结果怀疑','Even after the first successful test, the engineers were unconvinced that the prototype would survive a full winter.','即使第一次测试成功，工程师仍怀疑原型能否撑过整个冬季。','unconvinced that something will work; remain unconvinced','形容词，也表示怀疑某事能否发生或达到承诺效果。','一次测试不足以证明原型能耐受整冬。')],M('The committee was unconvinced by the report because it found every calculation convincing and accepted the conclusion immediately.','The committee was unconvinced by the report because it could not verify the calculations.','完全接受并认为论证充分，与unconvinced相反。'),[Q(1,'Why was the committee unconvinced?','The forecast did not explain its calculations.','The figures were fully explained and verified.','The report contained no forecast.','Sense 1 means not persuaded by an argument.','context'),Q(2,'What did the engineers doubt?','Whether the prototype would survive a full winter','Whether the first test had happened','Whether winter follows autumn','Sense 2 concerns whether a promised result will occur.','meaning'),Q(1,'Which construction is natural?','unconvinced by the evidence','unconvinced for the evidence','unconvinced evidence by the committee','Unconvinced commonly takes by before the argument.','grammar'),Q(2,'Which synonym fits the engineers’ view?','skeptical','certain','uncomplicated','They doubt the prototype will work as promised.','meaning')]);
P('unconvincing','Unconvincing is formed from un- + convincing, the -ing adjective from convince; it describes an argument that fails to persuade or a performance that seems unreal.',[
C('unconvincing.s1','论据','The explanation was unconvincing because it offered no measurements to support the claimed improvement.','这个解释缺乏说服力，因为没有提供任何测量数据支持所称的改进。','an unconvincing argument/explanation; sound unconvincing','形容词，表示理由薄弱，不能使人相信其真实性。','缺少测量证据使改进主张站不住脚。'),C('unconvincing.s2','表演','The actor’s unconvincing imitation of a doctor made the hospital scene feel artificial.','演员模仿医生的表演不真实，让医院场景显得很假。','an unconvincing performance/imitation; look unconvincing','形容词，表示表演或呈现方式显得不真实。','模仿不自然，观众无法相信角色形象。')],M('The explanation was unconvincing because it included complete measurements, independent checks, and clear supporting evidence.','The explanation was convincing because it included complete measurements and independent checks.','充分证据会增强说服力，与unconvincing判断冲突。'),[Q(1,'Why was the explanation unconvincing?','It lacked measurements supporting the claim.','It included complete independent evidence.','It was too short to be read.','Sense 1 is an argument too weak to persuade.','context'),Q(2,'Why did the hospital scene feel artificial?','The actor’s imitation did not seem real.','The actor followed a convincing medical routine.','The clinic had no patients.','Sense 2 describes an unrealistic performance.','meaning'),Q(1,'Which phrase is natural?','an unconvincing argument','an unconvincing argument that persuades everyone completely','unconvincing to explain the evidence','The adjective can describe an argument or explanation.','collocation'),Q(2,'Which is the best contrast?','A realistic portrayal is convincing.','A realistic portrayal is unconvincing.','A medical report is a tribunal.','The acting sense contrasts with a portrayal that feels real.','distinction')]);
P('uncooked','Uncooked is formed from un- + cooked; cook comes from Old English coc, borrowed from Latin coquere “cook.” It can mean not heated at all or insufficiently heated inside.',[
C('uncooked.s1','食材','The salad used uncooked vegetables, washed carefully and served fresh with the dressing.','沙拉使用了未烹煮的蔬菜，仔细清洗后与调味汁一起新鲜上桌。','uncooked vegetables/fish; eat something uncooked','形容词，指食物尚未经过加热烹调。','蔬菜被洗净后直接新鲜食用。'),C('uncooked.s2','未熟透','The center of the pie was still uncooked after the oven timer rang, so the baker returned it to the oven.','烤箱计时器响起后，馅饼中心仍未熟透，面包师便把它重新放回烤箱。','uncooked in the middle; leave food uncooked','形容词，也指加热时间太短、内部仍未熟的食物。','外层已烤但中心还没熟。')],M('The pie was uncooked in the center even though its filling was fully heated and safe to eat throughout.','The pie was uncooked in the center because the filling remained soft and needed more baking.','中心完全熟透与uncooked内部相反。'),[Q(1,'Were the salad vegetables heated?','No, they were served fresh and uncooked.','Yes, they were roasted for an hour.','They were unchangeable.','Sense 1 means not cooked before serving.','context'),Q(2,'Why did the baker return the pie to the oven?','The center was not fully cooked.','The crust was already frozen.','The oven timer was a treaty.','Sense 2 describes food heated for too short a time.','meaning'),Q(1,'Which phrase is natural?','uncooked vegetables','uncooked vegetables roasted until crisp','uncooked at the oven timer','Uncooked can describe fresh vegetables not heated.','collocation'),Q(2,'What does the pie example show?','Uncooked can mean underdone in the middle.','Uncooked always means raw throughout.','Uncooked means burnt on the outside.','The second sense includes food heated too briefly.','distinction')]);
P('uncooperative','Uncooperative is formed from un- + cooperative; cooperate comes from Latin cooperari “work together.” It describes someone unwilling to help or work with others.',C('uncooperative.s1','协作','The witness was uncooperative and refused to answer even basic questions about the damaged equipment.','证人不愿配合，连受损设备的基本问题也拒绝回答。','uncooperative witness/behavior; remain uncooperative','形容词，表示不愿合作或不肯提供帮助。','拒绝回答基本问题表现出不配合。'),M('The witness was uncooperative because she volunteered every requested detail and helped investigators throughout the interview.','The witness was cooperative because she volunteered details and helped investigators.','主动提供信息并协助调查是 cooperative，不是 uncooperative。'),[Q(1,'How did the witness behave?','She refused to answer basic questions.','She volunteered every requested detail.','She signed the treaty.','Uncooperative means unwilling to cooperate or help.','context'),Q(1,'Which phrase is natural?','an uncooperative witness','an uncooperative witness who eagerly assists','an uncooperative to investigators','Uncooperative commonly describes a witness or behavior.','collocation'),Q(1,'What does cooperate mean in the base word?','Work together','Break apart','Remain uncertain','Cooperate means work jointly; un- negates it.','word-formation'),Q(1,'What is the opposite of uncooperative?','helpful','uncompetitive','uncooked','A helpful person is willing to cooperate.','meaning')]);
P('uncorrupt','Uncorrupt combines un- + corrupt; corrupt came through Old French from Latin corrumpere “spoil.” It describes a person who is morally honest or a text free from corruption.',[
C('uncorrupt.s1','品格','The investigator found an uncorrupt official who refused every bribe offered by the contractor.','调查人员发现一名廉洁的官员，他拒绝了承包商提供的所有贿赂。','an uncorrupt official/judge; remain uncorrupt','形容词，表示道德上正直、没有被收买。','官员拒收贿赂，符合廉洁义。'),C('uncorrupt.s1','文本校勘','The editor compared several manuscripts to recover an uncorrupt version of the damaged passage.','编辑对照了几份手稿，试图还原受损段落未被篡改的版本。','an uncorrupt text/version; preserve an uncorrupt copy','也可指文字或记录没有讹误、篡改。','对照手稿用于恢复未受破坏的文本。')],M('The official was uncorrupt because he accepted secret payments to alter the contract.','The official was corrupt because he accepted secret payments to alter the contract.','接受秘密贿赂是腐败，而不是廉洁。'),[Q(1,'Why was the official called uncorrupt?','He refused every offered bribe.','He secretly accepted payments.','He changed the text of a manuscript.','The moral sense means honest and not corrupted.','context'),Q(1,'What is an uncorrupt version of a passage?','A text free from alteration or corruption','A passage deliberately altered to mislead','An uncertain oral rumor','The second use can describe an intact text.','meaning'),Q(1,'Which word is the opposite of uncorrupt in the bribery example?','corrupt','unbroken','uncompetitive','A bribed official is corrupt.','distinction'),Q(1,'Which collocation fits the textual sense?','an uncorrupt manuscript','an uncorrupt bribe accepted secretly','an uncorrupt with the passage','The word can describe a version or text without corruption.','collocation')]);
})(typeof window!=='undefined'?window:globalThis);

(function(global){
'use strict';
const RA=global.RA=global.RA||{};const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('uncorrupted','Uncorrupted is formed from un- + corrupted, the past participle of corrupt; it describes something still honest, pure, or free from alteration.',[
C('uncorrupted.s1','品格','The audit found an uncorrupted official who had refused gifts from every bidder.','审计发现一名廉洁的官员，他拒绝了所有投标者送来的礼物。','an uncorrupted judge/record; remain uncorrupted','形容词，表示品格未被腐蚀，或文本未被篡改。','拒绝利益输送表明官员没有被收买。'),C('uncorrupted.s1','文献','The archivist preserved an uncorrupted copy of the letter before later editors added notes.','档案员在后来的编辑添加注释前，保存了一份未被改动的信件副本。','an uncorrupted manuscript/version; preserve an uncorrupted copy','也可指内容保持原样、没有讹误或修改。','副本保留原文，未加入后来的注释。')],M('The archivist called the letter uncorrupted after changing its dates and deleting several original paragraphs.','The archivist kept an uncorrupted copy without changing its dates or wording.','更改日期并删段意味着文本已被篡改。'),[Q(1,'Why was the official described as uncorrupted?','He refused gifts from bidders.','He accepted payments to favor one bidder.','He rewrote the audit.','The moral sense means honest and not corrupted.','context'),Q(1,'What made the archived copy uncorrupted?','Its original wording and dates were preserved.','Editors deleted its original paragraphs.','The letter was never written.','The word also describes text free from alteration.','meaning'),Q(1,'Which phrase is natural?','an uncorrupted record','an uncorrupted record secretly rewritten','an uncorrupted by the bidder','The adjective can describe an honest official or an intact record.','collocation'),Q(1,'What does un- contribute?','It negates corruption or alteration.','It means below a record.','It marks a plural form.','Uncorrupted is the negative form of corrupted.','word-formation')]);
P('uncounted','Uncounted is formed from un- + count + -ed; it means not yet counted, or so numerous that no count has been made.',C('uncounted.s1','数量','Uncounted seedlings remained in the nursery trays after volunteers finished labeling the first batch.','志愿者给第一批幼苗贴完标签后，育苗盘里仍有许多未计数的幼苗。','uncounted votes/items; countless uncounted details','形容词，指尚未统计的数量，也可暗示多得无法逐一计数。','仍有幼苗留在盘中，说明它们还没纳入统计。'),M('The uncounted ballots had all been tallied, checked, and entered into the final total.','The uncounted ballots still needed to be tallied before the final result.','已全部统计的选票不能再称为uncounted。'),[Q(1,'What were the uncounted seedlings?','Seedlings not yet included in the count','Seedlings already labeled and tallied','Seedlings that had been planted years ago','The direct sense is not counted yet.','context'),Q(1,'What can uncounted suggest in “uncounted details”?','So many details that no full count has been made','Exactly one detail','Details already numbered and checked','The word may emphasize an immense or unspecified number.','meaning'),Q(1,'Which phrase is natural?','uncounted ballots','uncounted ballots already included in the final total','uncounted the ballot count','Uncounted commonly modifies votes, ballots, or items.','collocation'),Q(1,'What does -ed contribute in uncounted?','A state of having been counted, negated by un-','A person who counts','A future action','The adjective describes whether counting has occurred.','word-formation')]);
P('uncouth','Uncouth comes from Old English uncūth “unknown, unfamiliar,” from un- + cūth “known”; it developed meanings of rude behavior and rough lack of skill or finish.',[
C('uncouth.s1','礼仪','His uncouth remarks about the guests’ appearance embarrassed everyone at the formal dinner.','他在正式晚宴上对客人外貌发表粗鲁评论，让所有人都感到尴尬。','uncouth behavior/manners; seem uncouth','形容词，表示举止粗鲁、不懂礼貌。','公开评论客人外貌不合礼仪。'),C('uncouth.s2','粗糙技能','The apprentice’s first uncouth carving had uneven edges, but the next one was smoother.','学徒第一次粗糙的雕刻边缘不齐，不过下一件作品更平滑。','uncouth style/attempt; rough and uncouth','形容作品或技能粗糙、不熟练或缺少精致处理。','边缘不齐显示雕刻尚不熟练。')],M('His uncouth remarks were praised as perfectly courteous because they insulted no one and respected every guest.','His uncouth remarks embarrassed the guests because they were rude and disrespectful.','礼貌尊重的言辞不能称为uncouth。'),[Q(1,'Why were the dinner guests embarrassed?','His remarks about their appearance were rude.','He politely praised each guest.','The carving had uneven edges.','Sense 1 is rude or ill-mannered behavior.','context'),Q(2,'Why was the apprentice’s carving uncouth?','Its edges were rough and uneven.','It was a finished, polished masterpiece.','It had not been carved at all.','Sense 2 describes rough or unskilled work.','meaning'),Q(1,'Which phrase is natural?','uncouth manners','uncouth courteous manners','uncouth of the dinner','Uncouth often describes manners or behavior.','collocation'),Q(2,'Which synonym fits the rough carving?','crude','polished','undamaged','The work is rough and lacking refinement.','meaning')]);
P('uncover','Uncover is formed from un- + cover; cover came through Old French from Latin cooperire “cover over.” It means remove a covering or discover something hidden.',[
C('uncover.s1','移除覆盖物','Please uncover the bowl after the dough has rested so the cook can check its texture.','面团静置后请揭开碗上的盖子，让厨师检查质地。','uncover a dish/face; uncover the lid','及物动词，指移开盖子、布或其他覆盖物。','移开碗盖后才能看到面团。'),C('uncover.s2','揭露事实','The investigation uncovered evidence that the contractor had changed the inspection logs.','调查揭露了承包商篡改检查记录的证据。','uncover a secret/fact/crime; uncover evidence','及物动词，指发现此前被隐藏的秘密、事实或罪行。','调查找到此前隐藏的篡改证据。')],M('The investigation uncovered the fraud by concealing the altered logs and preventing anyone from finding them.','The investigation uncovered the fraud by discovering the altered logs.','继续隐藏证据不能称为揭露 fraud。'),[Q(1,'What did the cook do when she uncovered the bowl?','Removed its covering','Added a second lid','Changed the recipe’s date','Sense 1 is taking off a cover.','context'),Q(2,'What did the investigation uncover?','Evidence of altered inspection logs','A clean bowl cover','An unchangeable law','Sense 2 means discover something hidden.','meaning'),Q(1,'Which phrase is natural?','uncover a dish','uncover a dish by placing another lid over it','uncover into a dish','One can uncover a dish by removing its cover.','collocation'),Q(2,'What is the figurative meaning of uncover?','Bring hidden information to light','Cover something with cloth','Make a fact impossible to dispute','The investigation reveals evidence that had been concealed.','distinction')]);
P('uncovered','Uncovered is formed from un- + covered; it describes something with nothing over it or information that has not been discovered or exposed.',[
C('uncovered.s1','无遮盖','The workers left the equipment uncovered overnight, so rain collected in the open containers.','工人们夜里没有给设备加盖，雨水因此积在敞开的容器里。','leave/remain uncovered; uncovered ground','形容词，表示没有东西盖在表面上。','雨水能进入容器是因为它们敞开无盖。'),C('uncovered.s2','尚未发现','The source of the leak remained uncovered until a technician traced it to a cracked pipe.','直到技术人员追查到一根裂管，漏水原因才被发现。','remain uncovered; previously uncovered facts','形容秘密或事实尚未被发现或揭露。','裂管原因在技术人员调查前仍未查明。')],M('The containers were uncovered even though each one was sealed under a waterproof lid.','The containers were uncovered because they had no lids to keep rain out.','密封防水盖覆盖容器，所以不能称为uncovered。'),[Q(1,'Why did rain collect in the containers?','They were left without covers.','They were sealed under waterproof lids.','They were stored underground.','Sense 1 means having nothing over something.','context'),Q(2,'When was the leak’s source uncovered?','After the technician traced it to a cracked pipe','Before anyone inspected the system','When the containers were covered','Sense 2 means discovered or brought to light.','meaning'),Q(1,'Which phrase is natural?','leave food uncovered','leave food uncovered under a sealed lid','uncovered the food to cover it','Uncovered describes the absence of a covering.','collocation'),Q(2,'Which synonym fits “the source remained uncovered”?','undiscovered','exposed to rain','covered','The information had not yet been found.','meaning')]);
P('uncritical','Uncritical is formed from un- + critical; critical is related to Greek kritikos “able to judge.” Uncritical means not using careful judgment, or not finding fault.',[
C('uncritical.s1','判断思维','An uncritical reader accepted the advertisement’s claims without checking the independent test results.','一位缺乏批判性判断的读者没有查看独立测试结果就接受了广告说法。','uncritical acceptance/support; think uncritically','形容词，指没有仔细评估证据或判断。','读者未经核实便接受宣传结论。'),C('uncritical.s1','不挑剔','The reviewer was uncritical of the small timing error and focused instead on the film’s strong performances.','评论者没有挑剔那处小小的时间错误，而是把重点放在影片出色的表演上。','be uncritical of something; an uncritical review','也可表示不批评或不挑错。','评论者选择忽略小瑕疵。')],M('The reader was uncritical because she checked the claims against independent tests and rejected unsupported statements.','The reader was uncritical because she accepted the claims without checking supporting evidence.','核实证据并拒绝无依据说法体现审慎判断，而非uncritical。'),[Q(1,'Why was the reader uncritical?','She accepted the claims without checking evidence.','She compared the claims with independent tests.','She rejected every statement automatically.','Sense 1 means not exercising careful judgment.','context'),Q(1,'What does “uncritical of the small error” mean?','The reviewer did not find fault with it.','The reviewer proved the error was serious.','The reviewer refused to watch the film.','The source also uses uncritical to mean not critical of something.','meaning'),Q(1,'Which phrase is natural?','uncritical acceptance of an advertisement','uncritical evidence carefully checked','uncritical about of the claim','Uncritical commonly modifies acceptance, support, or review.','collocation'),Q(1,'What is the opposite of uncritical reading?','Careful evaluation of evidence','Accepting every claim immediately','Leaving a container uncovered','A critical reader examines evidence and reasoning.','distinction')]);
P('uncrumple','Uncrumple is formed from un- + crumple; it means remove the creases from paper or cloth that has been crushed or folded.',C('uncrumple.s1','纸张与衣物','She smoothed the receipt on the counter to uncrumple it before scanning the faded print.','她把收据在柜台上抚平，展开褶皱后才扫描褪色的字迹。','uncrumple a page/receipt; try to uncrumple paper','及物动词，表示展平被揉皱的纸或布。','扫描前需要把收据的皱褶抚平。'),M('She uncrumpled the receipt by squeezing it into a tighter ball.','She uncrumpled the receipt by smoothing its folds flat on the counter.','把纸揉得更紧会加重皱褶，而非uncrumple。'),[Q(1,'Why did she uncrumple the receipt?','To flatten it before scanning','To make it more tightly folded','To cover it with a lid','Uncrumple means remove creases.','context'),Q(1,'What can you uncrumple?','A piece of crumpled paper','A solid glass block','A legal tribunal','Paper or cloth can be uncrumpled.','meaning'),Q(1,'What does un- mean in uncrumple?','Reverse or remove the crumpling','Repeat the crumpling','Count the paper','The prefix reverses the action of crumpling.','word-formation'),Q(1,'Which verb is closest in meaning?','smooth out','crush further','undercut','Uncrumpling smooths folds or creases out.','meaning')]);
P('undamaged','Undamaged is formed from un- + damaged; damage came through Old French from Latin damnum “loss, harm.” It means not harmed or spoiled, including not physically injured.',[
C('undamaged.s1','物品状态','The parcel arrived undamaged because the ceramic cups were wrapped in padded sleeves.','陶瓷杯用缓冲套包好后，包裹完好无损地送达。','arrive/remain undamaged; undamaged goods','形容词，表示物品没有受损或变坏。','缓冲包装保护杯子在运输中未损坏。'),C('undamaged.s2','人身安全','Both passengers were undamaged in the minor collision and left the scene after speaking with police.','两名乘客在轻微碰撞中都没有受伤，与警方交谈后离开现场。','escape/remain undamaged; physically undamaged','形容人没有在事故或攻击中受伤。','乘客在碰撞后没有身体伤害。')],M('The parcel was undamaged even though the cups inside were smashed into fragments during delivery.','The parcel was damaged because the cups inside were smashed during delivery.','杯子碎裂说明包裹内物品受损，不能称undamaged。'),[Q(1,'How did the ceramic cups arrive?','Without damage','Broken into pieces','Uncooked','Sense 1 refers to objects that remain intact.','context'),Q(2,'What happened to the passengers?','They were not physically hurt.','They were injured in the collision.','They damaged the parcel.','Sense 2 concerns people not being harmed.','meaning'),Q(1,'Which phrase is natural?','the goods arrived undamaged','the goods arrived undamaged but were smashed','the goods undamaged into the box','Undamaged commonly describes goods or objects.','collocation'),Q(2,'Which meaning is used for the passengers?','Not physically injured','Not marked with a date','Not yet counted','The entry includes a personal safety sense.','distinction')]);
P('undated','Undated is formed from un- + date + -ed; it means not marked or identified with a date.',C('undated.s1','档案','The historian placed the undated photograph in a folder until its clothing and background could be identified.','历史学家把这张没有日期的照片放进文件夹，等待确认其中的服饰和背景。','an undated letter/photo/document; remain undated','形容词，表示没有标明写作、拍摄或发生日期。','照片尚无时间标记，需要进一步考证。'),M('The postcard was undated even though the sender had written a clear day, month, and year on it.','The postcard was dated because the sender wrote the day, month, and year on it.','标明完整日期的明信片不能称为undated。'),[Q(1,'Why did the historian call the photograph undated?','It had no date marked on it.','It showed the calendar clearly.','It had been counted twice.','Undated means not marked with a date.','context'),Q(1,'Which item could be undated?','A letter with no date written on it','A signed form stating the exact date','A timetable for next week','The adjective describes the absence of a date.','meaning'),Q(1,'Which phrase is natural?','an undated photograph','an undated photograph with the date printed clearly','undated by the year on its cover','Undated often modifies documents or images.','collocation'),Q(1,'What does un- contribute?','Not','Before','Three times','It negates “dated.”','word-formation')]);
P('undaunted','Undaunted is formed from un- + daunted, the past participle of daunt “intimidate, discourage”; it describes someone showing no fear or remaining eager after failure.',[
C('undaunted.s1','面对危险','The climbers remained undaunted by the storm forecast and waited for a safe weather window.','登山者没有被暴风预报吓倒，而是等待安全的天气窗口。','remain/be undaunted by danger; undaunted courage','形容词，表示面对危险或困难时没有畏惧。','他们没有因预报而放弃，仍计划在安全时攀登。'),C('undaunted.s2','挫折之后','Undaunted by two rejected applications, Nia revised her proposal and applied for the fellowship again.','两次申请被拒后，妮娅并未气馁，而是修改提案再次申请奖学金。','undaunted by failure/rejection; continue undaunted','形容词，表示失败或遭拒后仍愿意继续尝试。','她吸取经验并再次申请。')],M('Nia was undaunted by rejection because she abandoned the application forever and refused to try again.','Nia was undaunted by rejection because she revised the proposal and applied again.','永远放弃且拒绝再试，与undaunted所表达的未气馁相反。'),[Q(1,'How did the climbers react to the forecast?','They were not frightened into giving up.','They cancelled without considering conditions.','They ignored all safety procedures.','Sense 1 is not frightened by danger.','context'),Q(2,'Why was Nia undaunted by rejection?','She revised her proposal and applied again.','She gave up permanently.','She had never applied.','Sense 2 includes eagerness to try after failure.','meaning'),Q(1,'Which preposition is natural?','undaunted by the storm','undaunted of the storm','undaunted into the storm by','Undaunted is commonly followed by by.','grammar'),Q(2,'Which word best matches Nia’s response?','persistent','discouraged','uncompetitive','She continues despite rejection.','meaning')]);
P('undecided','Undecided is formed from un- + decided; decide comes from Latin decidere “cut off, determine.” It means not yet chosen or settled, or an election result still unknown.',[
C('undecided.s1','个人选择','I am still undecided about which evening course to take, so I am comparing the schedules.','我还没决定选哪门晚间课程，因此正在比较课表。','remain undecided about; an undecided choice','形容词，表示经过考虑后仍未作出选择。','说话者仍在比较不同课程。'),C('undecided.s2','选举结果','Several districts remained undecided while election officials counted the final ballots.','选举工作人员清点最后一批选票时，几个选区的结果仍未确定。','undecided voters/districts; remain undecided','形容选举结果尚未揭晓或确定。','选票还在统计，结果暂时未知。')],M('The district was undecided even though every ballot had been counted and the final winner announced.','The district remained undecided while officials counted the final ballots.','已清点所有选票并宣布获胜者意味着结果已确定。'),[Q(1,'Why was the speaker undecided about a course?','She was still comparing schedules.','She had already enrolled in one.','The course was unconstitutional.','Sense 1 means not yet chosen.','context'),Q(2,'Why did districts remain undecided?','Election officials were still counting ballots.','The winner had already been announced.','No one had voted.','Sense 2 refers to an election result not yet known.','meaning'),Q(1,'Which construction is natural?','undecided about which course to take','undecided which about course take','undecided on about the course which','Undecided commonly takes about before a choice.','grammar'),Q(2,'Which use concerns an election rather than a personal choice?','an undecided district','an undecided evening course','an undecided lunch order','The district’s result is still unknown.','distinction')]);
P('undemanding','Undemanding is formed from un- + demanding; demand is from Old French demander. It describes a task requiring little effort or a person easy to satisfy.',C('undemanding.s1','任务难度','The museum assigned an undemanding labeling task to new volunteers before they handled fragile artifacts.','博物馆先给新志愿者安排了简单的贴标签任务，然后才让他们接触易碎文物。','an undemanding job/task; undemanding routine','形容词，表示工作不费力或要求不高，也可指容易满足。','贴标签任务适合作为接触文物前的简单训练。'),M('The task was undemanding because it required advanced training, overnight work, and constant heavy lifting.','The task was demanding because it required advanced training and overnight work.','高强度要求与undemanding“要求低”相反。'),[Q(1,'Why was the labeling task undemanding?','It required little effort or specialized skill.','It required overnight work and advanced training.','It involved moving heavy artifacts.','The source sense is easy and not requiring hard work.','context'),Q(1,'An undemanding person may be…','easy to satisfy','impossible to please','unaware of everything','The word can also describe someone who does not ask for much.','meaning'),Q(1,'Which phrase is natural?','an undemanding routine','an undemanding routine requiring exhausting labor','undemanding to the routine','Undemanding commonly modifies a task, job, or routine.','collocation'),Q(1,'Which is closest in meaning for the task?','easy','arduous','uncertain','The task requires little effort.','meaning')]);
P('undeniable','Undeniable is formed from un- + deny + -able; deny came through Old French from Latin denegare “refuse.” It means so clearly true that it cannot reasonably be disputed.',C('undeniable.s1','证据','The audit found undeniable evidence that the invoice total had been entered twice.','审计发现了无可否认的证据，证明发票总额被重复录入。','undeniable evidence/fact; undeniable that','形容词，表示事实清楚，无法合理否认。','两条相同金额的录入记录构成明确证据。'),M('The audit called the duplicate entry undeniable, although the invoice had only one entry and no matching record.','The audit found undeniable evidence of the duplicate entry in two matching records.','没有重复记录却断言证据确凿，前后不一致。'),[Q(1,'What was undeniable in the audit?','Evidence that the invoice was entered twice','A rumor with no record','A claim the auditor had not checked','The adjective means clearly true and not reasonably disputable.','context'),Q(1,'Which phrase is natural?','undeniable evidence','undeniable evidence that does not exist','undeniable of the fact','Undeniable commonly modifies evidence, fact, or truth.','collocation'),Q(1,'What does -able mean in undeniable?','Capable of being denied, negated by un-','A person who denies','Already denied in the past','The morphology means it cannot be denied.','word-formation'),Q(1,'Which synonym fits?','indisputable','unclear','uncompetitive','Undeniable means impossible to dispute.','meaning')]);
P('under','Under comes from Old English under, from a Germanic word for a lower position; it can mean below or covered by, below an age or amount, during/according to authority, or insufficiently.',[
C('under.s1','位置','The spare key is under the flowerpot beside the back door.','备用钥匙在后门旁花盆的下面。','under the table/ground; hide something under','介词或副词，表示处于较低位置或被某物覆盖。','钥匙位于花盆下方。'),C('under.s2','数值限制','Children under twelve may enter the exhibition free with an adult.','十二岁以下儿童可在成人陪同下免费参观展览。','under age/price/weight; under twelve','介词，表示低于某个年龄、价格或数量。','年龄条件是未满十二岁。'),C('under.s3','期间/规则','Under the new safety rule, visitors must wear eye protection in the workshop.','根据新的安全规定，访客在车间必须佩戴护目镜。','under a rule/law/authority; under discussion','介词，表示在某制度、权威、条件或活动期间。','护目镜要求由新规规定。'),C('under.s4','不足','The bridge is under repair because its supports need reinforcement.','这座桥正在维修，因为支撑结构需要加固。','under repair/construction; understrength','前缀式用法，表示处于不足、未完成或低于标准的状态。','桥尚未维修完毕，仍处在施工状态。')],M('Children under twelve means children older than twelve and therefore above the stated age limit.','Children under twelve means children younger than twelve.','under + age 表示低于该年龄，不是高于。'),[Q(1,'Where is the spare key?','Below the flowerpot','Inside the workshop rule','Above the roof','Sense 1 indicates a lower position.','context'),Q(2,'Who may enter free?','Children younger than twelve with an adult','Children older than twelve alone','Only adults under repair','Sense 2 means below a stated age.','meaning'),Q(3,'What does “under the new rule” mean?','According to the new rule','Below the physical rulebook','After the rule was cancelled','Sense 3 refers to authority or regulation.','meaning'),Q(4,'What does “under repair” mean?','Being repaired and not yet complete','Finished and ready for use','Located beneath a repair worker','Sense 4 indicates an incomplete state.','distinction')]);
P('under which','Under which combines under + the relative pronoun which; it refers back to a place below something or to a situation or set of conditions.',[
C('under which.s1','位置关系','They inspected the bridge under which the river narrows into a deep channel.','他们检查了河流在其下方收窄成深水道的那座桥。','the bridge under which; a tunnel under which','关系结构，which 回指前面的地点或物体，under 表示其下方。','which 指回 bridge，河道位于桥下。'),C('under which.s2','条件关系','The contract sets out the conditions under which the laboratory may share its research data.','合同列明了实验室可以共享研究数据的条件。','conditions under which; circumstances under which','关系结构，which 回指前面的条件或情况。','which 指回 conditions，后文说明数据共享的适用条件。')],M('The contract describes the conditions under which data may be shared, but it never states any conditions or circumstances.','The contract describes the conditions under which data may be shared with partners.','under which 引出前文 conditions 的具体内容；完全没有条件则不成立。'),[Q(1,'What lies under which object in the first example?','A river channel lies below the bridge.','The bridge lies below the river.','A contract lies below the laboratory.','Sense 1 refers back to a physical place or object.','context'),Q(2,'What does which refer back to in “conditions under which”?','The conditions','The laboratory data itself','The bridge above the river','Sense 2 refers to a situation or set of conditions.','meaning'),Q(2,'Which phrase is standard?','the rules under which a permit is issued','the rules under which issued a permit them','the permit under which rules by','Under which follows a noun it refers back to.','grammar'),Q(1,'What relation does under express in “the bridge under which…”?','A location below the bridge','A cause of the bridge','A price lower than a bridge','The first use is a spatial relative construction.','distinction')]);
P('underbrush','Underbrush combines under + brush, where brush refers to shrubs; it names dense low shrubs and saplings growing beneath a forest canopy.',C('underbrush.s1','林地','The survey crew moved slowly through underbrush beneath the old pines to mark the boundary stones.','测绘队在老松树下的浓密灌木丛中缓慢前行，寻找并标记界石。','dense/thick underbrush; clear underbrush','不可数名词，指林冠下方的低矮灌木和幼树。','低矮灌木使队伍难以快速穿行。'),M('The hikers crossed dense underbrush beneath the pines even though the ground was bare and free of shrubs.','The hikers crossed dense underbrush made up of shrubs and saplings beneath the pines.','没有灌木的裸地不能称为dense underbrush。'),[Q(1,'What is underbrush?','Dense shrubs and young trees beneath a forest canopy','The top branches of a tree','Clothing worn under outer garments','The word names low vegetation under the trees.','meaning'),Q(1,'Why did the survey crew move slowly?','Shrubs and saplings made the route dense.','The path was a smooth paved road.','The trees had no canopy.','The underbrush obstructed quick movement.','context'),Q(1,'Which verb naturally goes with underbrush?','clear underbrush','wear underbrush','underbrush the river into a treaty','People may clear or move through underbrush.','collocation'),Q(1,'What does under indicate in underbrush?','Its position beneath taller trees','That it is below a stated age','That it is being counted','Brush grows beneath the forest canopy.','word-formation')]);
P('undercharge','Undercharge is formed from under- “too little” + charge; charge came through French from Latin carricare “load.” As a verb it means bill too little; as a noun it is the amount not charged.',[
C('undercharge.s1','收费','The shop undercharged the customer by ten dollars because the cashier entered the sale price incorrectly.','收银员输错售价，商店少收了顾客十美元。','undercharge a customer; undercharge for a service','及物动词，指收费低于应收金额。','实际付款比正确售价少十美元。'),C('undercharge.s1','差额','The accountant corrected the undercharge on the invoice before the monthly accounts closed.','会计在月度账目结算前更正了发票上的少收款项。','correct/pay an undercharge; an undercharge of $10','名词，指少收的金额。','发票上的差额被会计补正。')],M('The shop undercharged the customer by billing her ten dollars more than the listed price.','The shop overcharged the customer by billing ten dollars more than the listed price.','收费高于标价是overcharge，不是undercharge。'),[Q(1,'What did the shop do to the customer?','Charged ten dollars less than it should have','Charged ten dollars extra','Charged exactly the listed price','Undercharge as a verb means bill too little.','context'),Q(1,'What did the accountant correct?','The amount missing from the invoice','A ten-dollar overpayment','A date that was not written','The noun can name the shortfall in the charge.','meaning'),Q(1,'Which preposition is natural?','undercharge someone for a service','undercharge someone of a service','undercharge to the customer for','Undercharge can take a person as object and for the service.','grammar'),Q(1,'What is the opposite of undercharge?','overcharge','uncooked','underbrush','Overcharge means bill too much.','distinction')]);
P('underclothes','Underclothes combines under + clothes; it names clothing worn next to the skin beneath outer garments.',C('underclothes.s1','服装','She packed clean underclothes beneath her sweaters before leaving for the weeklong trip.','她在出发进行为期一周的旅行前，把干净的贴身衣物放在毛衣下面收进行李。','change/wash underclothes; a set of underclothes','复数名词，指穿在外衣里面、通常贴身的衣物。','衣物被放在毛衣下方且用于贴身穿着。'),M('He wore his underclothes over his coat so they would be the outermost layer.','He wore his underclothes beneath his coat, next to his skin.','underclothes 指外衣里面穿着的贴身衣物。'),[Q(1,'What are underclothes?','Clothes worn next to the skin under outer garments','A coat worn over every other layer','A type of forest shrub','The compound describes clothing worn underneath.','meaning'),Q(1,'Where did she pack her underclothes?','Beneath her sweaters in the suitcase','Over the outside of her coat','Under the road','The context places them below the outer garments.','context'),Q(1,'Which verb is natural?','wash underclothes','underclothes the sweater','underclothes with the forest','Underclothes are garments one can wash or change.','collocation'),Q(1,'Why is under- used in this compound?','The garments are worn beneath outer clothes.','They are too small to count.','They are unchangeable.','The prefix gives the clothing’s position in layers.','word-formation')]);
P('undercut','Undercut combines under + cut; in business it means offer goods or labor more cheaply than competitors, weakening their trade.',C('undercut.s1','商业竞争','The new supplier undercut its rivals by offering the same steel parts at a lower price.','新供应商以更低价格提供相同钢制零件，从而压低了竞争对手的价格。','undercut a competitor; undercut prices/wages','及物动词，指以更低价格竞争，使对手处于劣势。','同样产品售价更低，会削弱其他供应商的竞争力。'),M('The supplier undercut its rivals by charging twice as much for identical steel parts.','The supplier undercut its rivals by charging less for identical steel parts.','收费是对手两倍不是低价竞争。'),[Q(1,'How did the supplier undercut its rivals?','It offered the same parts at a lower price.','It charged twice as much.','It stopped selling steel parts.','Undercut means compete by offering a lower price.','context'),Q(1,'What can undercut weaken?','A competitor’s trade or position','A bridge support from below only','A person’s ability to cook','The source sense concerns commercial competition.','meaning'),Q(1,'Which phrase is natural?','undercut a competitor’s prices','undercut a price by doubling it','undercut of the rival','Companies may undercut competitors by offering lower prices.','collocation'),Q(1,'Which price strategy is an undercut?','Selling an identical part for less than a rival','Charging more than every rival','Keeping prices exactly the same','The term implies a lower competing price.','distinction')]);
P('underdeveloped','Underdeveloped is formed from under- + developed; develop came through French développer “unwrap, unfold.” It describes a place with limited industry or services, or something not grown to its usual stage.',[
C('underdeveloped.s1','经济发展','The report identified an underdeveloped district where transport, clinics, and reliable utilities remained scarce.','报告指出一个发展不足的地区，当地交通、诊所和稳定公用设施都较少。','underdeveloped region/economy; economically underdeveloped','形容词，指产业、收入或公共服务的发展程度较低。','公共服务不足说明该地区发展水平有限。'),C('underdeveloped.s2','生长阶段','The veterinarian monitored an underdeveloped foal whose legs had not reached the usual size for its age.','兽医持续观察一匹发育不足的小马，它的腿还没有达到同龄马的通常尺寸。','underdeveloped muscles/organs; underdeveloped for its age','形容词，指身体或事物尚未达到通常大小或发展阶段。','腿部尺寸未达到同龄正常水平。')],M('The district was underdeveloped because it had abundant clinics, transport, industry, and services for every resident.','The district was underdeveloped because clinics, transport, industry, and services were scarce.','公共服务和产业极为充足与underdeveloped地区特征相反。'),[Q(1,'Why was the district called underdeveloped?','It lacked transport, clinics, and reliable utilities.','It had extensive services and industry.','Its foal had short legs.','Sense 1 concerns limited economic and public development.','context'),Q(2,'What was unusual about the foal?','Its legs had not reached the usual size for its age.','It lived in a district with few clinics.','It was fully grown and oversized.','Sense 2 means not grown to a normal stage or size.','meaning'),Q(1,'Which phrase is natural for sense 1?','an underdeveloped region','an underdeveloped region with abundant services and industry','underdeveloped at a transport','It commonly describes a region or economy.','collocation'),Q(2,'Which example is about physical growth?','underdeveloped muscles','an underdeveloped economy','underdeveloped transport services','Sense 2 concerns a body part not reaching normal growth.','distinction')]);
})(typeof window!=='undefined'?window:globalThis);

(function(global){
'use strict';
const RA=global.RA=global.RA||{};const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('underdevelopment','Underdevelopment is formed from under- + development; it names insufficient economic, physical, or technical development.',C('underdevelopment.s1','经济与公共服务','The report linked underdevelopment in the valley to limited roads, schools, and reliable electricity.','报告把山谷地区发展不足与道路、学校和稳定电力有限联系起来。','economic/technical underdevelopment; address underdevelopment','不可数名词，表示产业、基础设施或技术发展不足。','多种公共服务不足说明发展水平不充分。'),M('The report described underdevelopment in the valley even though every village had modern roads, schools, and reliable utilities.','The report described underdevelopment because the valley lacked roads, schools, and reliable utilities.','公共服务普及与发展不足的判断相冲突。'),[Q(1,'What can underdevelopment refer to?','Insufficient economic, physical, or technical development','A fully developed network of services','A three-month period','The source sense covers development that is insufficient.','meaning'),Q(1,'What evidence supported the report’s conclusion?','Limited roads, schools, and electricity','A complete modern service network','A bridge with no supports','The context lists development gaps.','context'),Q(1,'Which phrase is natural?','economic underdevelopment','economic underdevelopment with every service fully developed','underdevelopment to a valley','Underdevelopment commonly follows an adjective such as economic.','collocation'),Q(1,'Which noun is the base of underdevelopment?','development','underlying','underdone','The word adds under- to development.','word-formation')]);
P('underdone','Underdone combines under- “insufficiently” + done, the past participle of do; it describes food heated for too short a time and still soft or not ready inside.',C('underdone.s1','烹饪','The baker cut into the loaf and found the center underdone, so she returned it to the oven.','面包师切开面包后发现中心还没烤熟，于是把它放回烤箱。','underdone meat/loaf; a little underdone','形容词，表示食物加热时间不足、内部仍未熟透。','中心仍软，说明烘烤时间不够。'),M('The roast was underdone even though it had been cooked until the center was fully firm and ready to eat.','The roast was underdone because its center was still soft and needed more cooking.','内部完全熟透与underdone相反。'),[Q(1,'Why did the baker return the loaf to the oven?','Its center was still insufficiently cooked.','The center was burned to charcoal.','The loaf was already frozen.','Underdone means heated for too short a time.','context'),Q(1,'What does underdone describe?','Food not cooked enough inside','Food cooked for too long and burned','An undecided election','The word describes insufficient cooking.','meaning'),Q(1,'Which phrase is natural?','the steak was slightly underdone','the steak was underdone because it was fully cooked throughout','the steak underdone to the plate','Underdone commonly describes food such as meat or bread.','collocation'),Q(1,'What does under- contribute here?','Less than the required amount of cooking','A position beneath the oven','A completed action','Under- means insufficiently in underdone.','word-formation')]);
P('underestimate','Underestimate is formed from under- “too little” + estimate; estimate came from Latin aestimare “value, assess.” It means judge an amount too low, think a person less able than they are, or a low estimate.',[
C('underestimate.s1','数量判断','We underestimated the paint needed and had to order two more cans before finishing the hall.','我们低估了所需油漆量，走廊完工前只好再订两罐。','underestimate the cost/time/amount; seriously underestimate','及物动词，指估计数量、程度或困难低于实际。','实际用量超过最初估计。'),C('underestimate.s2','能力判断','The opposing coach underestimated the young goalkeeper, who stopped every penalty shot.','对方教练低估了这位年轻守门员的能力，结果她挡下了所有点球。','underestimate someone’s ability; do not underestimate','及物动词，指认为某人的能力或价值低于实际。','守门员的表现超出对手预期。'),C('underestimate.s3','过低估值','The original budget was an underestimate because it omitted the cost of permits and inspection.','原预算是一个过低的估算，因为它漏掉了许可证和检查费用。','a serious/rough underestimate; prove an underestimate','可数名词，指低于实际值的估计。','漏项使预算估计低于最后实际成本。')],M('We underestimated the paint needed by ordering twice the amount required, leaving many unopened cans.','We overestimated the paint needed by ordering twice the amount required.','订购实际所需两倍属于高估，而非低估。'),[Q(1,'Why did the team order more paint?','It had underestimated the amount needed.','It had already ordered too much.','The paint was undercooked.','Sense 1 means estimate too low.','context'),Q(2,'What did the opposing coach underestimate?','The goalkeeper’s ability','The price of paint','The cost of permits','Sense 2 concerns judging a person’s ability too low.','meaning'),Q(3,'What was the original budget?','An estimate lower than the actual cost','A final exact invoice','A high estimate of every expense','Sense 3 is the noun for a low estimate.','meaning'),Q(2,'Which sentence uses underestimate about a person?','They underestimated the rookie’s skill.','They underestimated the travel cost.','Their estimate was an underestimate.','The direct object skill refers to the person’s ability.','distinction')]);
P('underfoot','Underfoot combines under + foot and means on the ground beneath someone or so close that it is nearly stepped on.',C('underfoot.s1','地面位置','Wet leaves gathered underfoot along the woodland path after the night rain.','夜雨过后，林间小路上脚下堆积着湿树叶。','leaves/debris underfoot; get underfoot','副词或形容词，指在脚下或近到妨碍走路。','树叶位于行走者脚下。'),M('The glass shards were underfoot on the path but safely stored on a high shelf far above everyone’s feet.','The glass shards were underfoot on the path, so the workers swept them away.','“脚下”与“放在高架上”互相矛盾。'),[Q(1,'Where were the wet leaves?','On the ground beneath the walkers’ feet','High above the tree canopy','Inside a sealed lunchbox','Underfoot means on or near the ground beneath someone.','context'),Q(1,'Why might clutter underfoot be a problem?','People could trip over it.','It is safely stored overhead.','It has no relation to walking.','Something underfoot may be so close that it impedes steps.','meaning'),Q(1,'Which phrase is natural?','debris underfoot','debris underfoot on a high shelf','underfoot to the path','The word commonly describes material on the ground.','collocation'),Q(1,'What does foot contribute in underfoot?','The position is relative to someone’s feet.','A unit of money','A person’s legal authority','The compound locates something below or near the feet.','word-formation')]);
P('undergarments','Undergarments combines under + garments; garment entered English through Old French for clothing, and the compound names clothes worn beneath outer garments.',C('undergarments.s1','服装','The travel list reminded hikers to pack dry undergarments for each day of the wet expedition.','旅行清单提醒徒步者为潮湿的探险之旅每天准备干燥的贴身衣物。','wear/change/pack undergarments; thermal undergarments','复数名词，指穿在外衣里面的内衣或贴身衣物。','这些衣物按天更换并穿在外层衣服里面。'),M('She wore her undergarments over a raincoat as the visible outer layer of the outfit.','She wore her undergarments next to the skin beneath her outer clothes.','undergarments 是外衣里面的贴身衣物，不是外层雨衣。'),[Q(1,'What are undergarments?','Clothes worn beneath outer garments','A coat worn over all other clothes','A forest’s low shrubs','The compound describes clothing underneath.','meaning'),Q(1,'Why did hikers pack dry undergarments?','They needed clean clothing for each day of a wet expedition.','They would wear them on top of raincoats.','They were planning to repair a bridge.','The clothing is worn next to the skin beneath outer layers.','context'),Q(1,'Which phrase is natural?','change into dry undergarments','wear undergarments over a raincoat as outerwear','undergarments a hiking route','People can pack or change undergarments.','collocation'),Q(1,'How does under- function in undergarments?','It describes their position beneath outer clothing.','It means they are too large.','It means they cannot be changed.','The prefix indicates where the garments are worn.','word-formation')]);
P('undergo','Undergo comes from Old English undergān, “submit to, experience,” combining under + go; it means experience a change or ordeal, or have treatment or inspection done.',[
C('undergo.s1','经历','The old theater will undergo major repairs before reopening to the public next spring.','这座老剧院将在明年春天重新开放前进行大规模维修。','undergo change/testing/repair; undergo a transformation','及物动词，表示经历变化、考验或困难。','剧院将经历一段大规模维修过程。'),C('undergo.s2','医疗/检查','The patient will undergo a scan tomorrow to determine whether the treatment has worked.','患者明天将接受扫描，以确定治疗是否有效。','undergo surgery/testing/an examination','及物动词，表示接受医疗处理或官方检查。','扫描将由医疗人员对患者进行。')],M('The patient underwent a scan, but no scan or examination was performed on her.','The patient underwent a scan performed by the radiology team.','undergo treatment means experience/receive treatment; if nothing is done, she did not undergo it.'),[Q(1,'What will the theater undergo?','Major repairs','A medical scan','A forest inspection below ground','Sense 1 is experiencing a process or change.','context'),Q(2,'Why will the patient undergo a scan?','To check whether the treatment worked','To reopen a theater','To avoid every examination','Sense 2 means receive or have a medical procedure.','meaning'),Q(1,'Which phrase is natural?','undergo a transformation','undergo to a transformation','undergo of transformation','Undergo is transitive and takes the process directly.','grammar'),Q(2,'Which use is medical?','undergo surgery','undergo a theater renovation','undergo a budget estimate','The medical sense covers treatment or procedures done to a patient.','distinction')]);
P('undergrad','Undergrad is a shortened form of undergraduate; it names a university student working toward a first degree.',C('undergrad.s1','大学教育','The undergrad worked in the chemistry lab between lectures while completing her first degree.','这名本科生在完成第一个学位期间，课间在化学实验室工作。','college/university undergrad; first-year undergrad','可数名词，口语缩略形式，指攻读第一个大学学位的学生。','她正在攻读第一个学位，符合 undergraduate student。'),M('The undergrad had already completed a doctorate and was no longer studying for a first degree.','The undergrad was still studying toward a first university degree.','已完成博士学位的人不再是攻读首个学位的本科生。'),[Q(1,'Who is an undergrad?','A university student working toward a first degree','A student who has already earned a doctorate','A university professor','Undergrad is short for undergraduate student.','meaning'),Q(1,'What was the undergrad doing in the lab?','Working between lectures while completing her first degree','Teaching every class as a professor','Inspecting a legal tribunal','The context describes an enrolled university student.','context'),Q(1,'Which phrase is natural?','a first-year undergrad','a first-year undergrad who has completed a doctorate','undergrad to the lecture','Undergrad is commonly modified by year or college.','collocation'),Q(1,'What is undergrad short for?','undergraduate','underdevelopment','underfoot','The word is an informal clipping of undergraduate.','word-formation')]);
P('undergraduate','Undergraduate is formed from under- + graduate, with graduate from Latin gradus “step”; it means a student pursuing a first degree or describes the period before that degree.',[
C('undergraduate.s1','学生身份','The undergraduate presented her research poster at the university’s annual science fair.','这名本科生在大学年度科学展上展示了自己的研究海报。','undergraduate student/course; enroll as an undergraduate','可数名词，指正在攻读第一个大学学位的学生。','她以本科生身份在校内展示研究。'),C('undergraduate.s2','学位阶段','The university expanded its undergraduate programs in engineering and environmental science.','大学扩展了工程和环境科学本科阶段的课程。','undergraduate degree/study/program','形容词，指获得第一个学位之前的大学教育阶段。','engineering programs属于第一学位阶段课程。')],M('The university called its doctoral program undergraduate study even though every student already held a first degree.','The university called its first-degree programs undergraduate study.','博士阶段在获得首个大学学位之后，不属于undergraduate。'),[Q(1,'Who presented the research poster?','A student working toward a first degree','A student who had already completed a doctorate','A court judge','Sense 1 is a student before the first degree.','context'),Q(2,'What does undergraduate describe in “undergraduate programs”?','Study before a first university degree','Postdoctoral research','A high-school-only course','Sense 2 is an adjective for the first-degree stage.','meaning'),Q(1,'Which phrase is standard?','undergraduate student','undergraduate student who already holds a doctorate as a first degree','undergraduate of student','Undergraduate commonly modifies student or study.','collocation'),Q(2,'Which word class is undergraduate in “undergraduate programs”?','Adjective','Adverb','Preposition','It modifies the noun programs.','grammar')]);
P('underground','Underground combines under + ground; it can mean below the earth’s surface, secretly because prohibited, hidden beneath a surface, or a city rail system or secret political group.',[
C('underground.s1','地理位置','The cable runs underground from the substation to the hospital.','电缆从变电站到医院沿地下铺设。','underground tunnel/cable; travel underground','副词或形容词，表示在地面以下。','电缆没有架在地面或空中，而是埋在地下。'),C('underground.s2','秘密活动','The banned newspaper was printed underground and distributed through a network of volunteers.','这份被禁报纸在秘密状态下印刷，并通过志愿者网络分发。','operate/go underground; underground press','形容秘密进行、因为不被允许而隐藏的活动。','报纸被禁止，因此印刷与分发需秘密进行。'),C('underground.s3','表面之下','The miners found a stream underground, flowing beneath the dry surface of the plateau.','矿工在地下发现一条溪流，它流经高原干燥地表之下。','flow underground; underground water','形容词或副词，表示在表面之下或进入隐蔽处。','水流位于地表之下。'),C('underground.s4','城市交通','We took the Underground across London to avoid the crowded roads above.','我们乘伦敦地铁横穿城市，以避开地面拥堵的道路。','the Underground; take/ride the underground','专名可指城市地下铁路系统，也可指秘密政治组织。','乘客使用的是城市轨道交通。')],M('The London Underground is an underground rail system that runs entirely on the rooftops above the city streets.','The London Underground is a rail system that runs beneath the city streets.','地铁的underground义指地下轨道，不是屋顶上运行。'),[Q(1,'Where does the cable run?','Below the earth’s surface','On the rooftop above the hospital','Inside a rail carriage','Sense 1 is the physical position below ground.','context'),Q(2,'Why was the newspaper printed underground?','It was banned and had to be distributed secretly.','It was printed in a subway station for tourists.','It was buried as treasure.','Sense 2 is secret activity because it is prohibited.','meaning'),Q(3,'Where did the miners find the stream?','Beneath the plateau’s surface','On the dry surface','Inside a city railway station','Sense 3 refers to what lies below a surface.','context'),Q(4,'What is the London Underground?','A city rail system','A prohibited newspaper','A stream below a plateau','Sense 4 is the urban railway system.','meaning')]);
P('underlie','Underlie comes from Old English underlicgan, combining under + lie; it means be the hidden basis or cause of something, or lie directly below it.',[
C('underlie.s1','根本原因','A lack of trust underlies the disagreement between the two research teams.','缺乏信任是两个研究团队产生分歧的根本原因。','underlie a conflict/assumption; reasons underlying a decision','及物动词，表示构成某事物的隐藏基础或原因。','不信任是可见争论背后的原因。'),C('underlie.s2','空间位置','A layer of clay underlies the gravel across most of the construction site.','施工场地的大部分区域里，砾石层下方都铺着一层黏土。','rock/layer underlies something; directly underlie','及物动词，表示实际位于某物正下方。','黏土层在砾石层之下。')],M('A lack of trust underlies the agreement because both teams trust each other completely and no disagreement exists.','A lack of trust underlies the disagreement because the teams doubt each other’s results.','完全互信、无分歧与缺乏信任作为根因相冲突。'),[Q(1,'What underlies the teams’ disagreement?','A lack of trust','A clay layer beneath gravel','A city rail line','Sense 1 is a hidden basis or cause.','context'),Q(2,'What layer lies beneath the gravel?','Clay','A layer of trust','A layer of rainwater above the roof','Sense 2 describes physical position below.','meaning'),Q(1,'Which phrase is natural for a cause?','a belief underlies the policy','a belief underlies beneath the policy','a belief underlies to the policy','Underlie can take a conflict, decision, or policy as its object.','grammar'),Q(2,'Which sentence uses the physical sense?','Clay underlies the gravel.','Fear underlies the decision.','Trust underlies the argument.','The first sentence describes one geological layer below another.','distinction')]);
P('underlies','Underlies is the third-person singular present form of underlie, from Old English underlicgan; it means serves as a hidden basis or lies beneath something.',C('underlies.s1','原因与基础','A shared assumption underlies both proposals, even though the teams recommend different designs.','尽管两个团队推荐的设计不同，但两份方案都基于同一个共同假设。','assumption underlies a claim; principle underlies a system','第三人称单数动词形式，表示构成隐藏基础或原因。','共同假设支撑着两份不同方案。'),M('A shared assumption underlies both proposals, although neither proposal rests on or uses that assumption.','A shared assumption underlies both proposals and supports their reasoning.','若两份方案都不依赖该假设，它就不能构成它们的基础。'),[Q(1,'What does the shared assumption do?','It provides a hidden basis for both proposals.','It lies beneath a gravel layer physically.','It rejects both proposals.','Underlies means serves as a basis or cause.','meaning'),Q(1,'Which verb form agrees with “a shared assumption”?','underlies','underlie','underlying','A singular third-person subject takes underlies.','grammar'),Q(1,'Which phrase is natural?','a principle underlies the system','a principle underlies to the system','a principle are underlies the system','Underlie takes a direct object without “to.”','collocation'),Q(1,'What is the base verb?','underlie','underline','undermine','Underlies is the inflected form of underlie.','word-formation')]);
P('underline','Underline is formed from under + line; it means draw a line beneath written text, emphasize a point, or the line itself.',[
C('underline.s1','标记文字','Please underline the two dates in the paragraph before comparing them with the archive record.','请先在段落中的两个日期下画线，再与档案记录进行比较。','underline a word/name/date; underline in red','及物动词，指在文字下方画线标记。','在日期下面作线便于查找。'),C('underline.s2','强调','The failed inspection underlined the need for a second safety check.','检查未通过这一结果凸显了再次进行安全检查的必要性。','underline the importance/need; facts underline a point','及物动词，比喻表示强调某事实或观点。','失败的检查让安全复核的重要性更加明显。'),C('underline.s3','线条','A faint underline beneath the heading showed where the previous editor had marked the title.','标题下方淡淡的线条显示了上一位编辑标记标题的位置。','draw/add an underline; a short underline','可数名词，指文字下方画出的线。','句子把underline作为线条本身来描述。')],M('She underlined the date by drawing a line above the paragraph, leaving no mark beneath the date.','She underlined the date by drawing a line directly beneath it.','underline 的字面义是在文字下方画线。'),[Q(1,'What did she do to the dates?','Drew a line beneath them','Circled the paragraph’s title only','Covered them with paint','Sense 1 is the literal marking action.','context'),Q(2,'What did the failed inspection underline?','The need for another safety check','The text of the date','A faint line beneath a title','Sense 2 means emphasize or make clear.','meaning'),Q(3,'What was faint beneath the heading?','A drawn line','A safety inspection','An underground cable','Sense 3 is the noun for the mark itself.','context'),Q(2,'Which synonym fits “underlined the need”?','emphasized','hid','undercharged','The figurative verb means made the need especially clear.','meaning')]);
P('underling','Underling combines under + -ling, a suffix used in nouns for a person; it names a subordinate, often one treated as unimportant.',C('underling.s1','职场等级','The director sent an underling to deliver the routine paperwork while she met with the board.','主管与董事会开会时，派了一名下属递送日常文件。','junior/low-ranking underling; an underling of a powerful official','可数名词，指地位较低的下属，常带轻蔑意味。','此人被派去处理日常事务，职位低于主管。'),M('The director’s underling was the company’s highest-ranking leader with authority over the director.','The director’s underling was a junior employee who reported to her.','underling 指低级下属，不是级别高于主管的领导。'),[Q(1,'Who is an underling?','A subordinate, often treated as unimportant','The chief executive above the director','A tribunal that reviews evidence','The source sense is a lower-ranking subordinate.','meaning'),Q(1,'Why did the director send the underling?','To deliver routine paperwork while she met the board','To replace the board permanently','To conduct an election','The context shows a subordinate carrying out a task.','context'),Q(1,'Which phrase is natural?','a junior underling','a junior underling who outranks the director','underling into a contract','Underling commonly appears with a low-ranking or junior role.','collocation'),Q(1,'What tone can underling carry?','Dismissive or belittling','Always highly honorific','A neutral scientific unit','The word often implies the subordinate is considered unimportant.','register')]);
P('underlying','Underlying is formed from under + lie + -ing; it means physically below something or hidden beneath the surface as a basic cause.',[
C('underlying.s1','物理层面','A layer of compacted gravel formed the underlying base beneath the garden path.','一层压实的碎石构成了花园小径下面的基础层。','underlying rock/layer; underlying structure','形容词，指实际位于另一层下方。','碎石层位于小路表层之下并起支撑作用。'),C('underlying.s2','根本问题','The mediator looked for the underlying concern behind the neighbors’ argument about the fence.','调解员试图找出邻居围栏争执背后的根本顾虑。','underlying cause/issue/assumption; identify underlying concerns','形容词，指表面现象之下隐藏的根本原因或问题。','围栏争论背后还有更深层的顾虑。')],M('The underlying cause of the dispute was obvious on the surface and had no deeper issue or hidden concern.','The underlying cause of the dispute was a hidden concern about the property boundary.','称为underlying cause的因素是潜在根因，不是毫无深层问题。'),[Q(1,'What formed the underlying base of the garden path?','Compacted gravel below the path','The visible flowers above it','A courtroom ruling','Sense 1 describes a physical layer below another.','context'),Q(2,'What was the mediator looking for?','A hidden concern beneath the surface argument','The gravel under the path','A line drawn under the contract','Sense 2 is a basic hidden cause or issue.','meaning'),Q(1,'Which phrase is natural?','underlying rock layer','underlying rock layer above the visible surface only','underlying to the rock','Underlying commonly modifies a base or physical layer.','collocation'),Q(2,'Which adjective is closest in “underlying cause”?','fundamental','visible','uncooked','The underlying cause is the fundamental issue behind events.','meaning')]);
P('undermine','Undermine combines under + mine; historically it referred to digging beneath a structure, and now it also means weaken a person, effort, feeling, or authority gradually.',[
C('undermine.s1','削弱信任','Repeatedly changing the safety rules undermined workers’ confidence in the new manager.','反复更改安全规定削弱了员工对新经理的信任。','undermine confidence/authority; undermine an effort','及物动词，比喻指逐渐削弱信任、努力或权威。','规则反复变化让员工不再信任经理。'),C('undermine.s2','侵蚀地基','Water undermined the stone wall by washing soil away from its base.','水冲走石墙底部的土壤，逐渐掏空了墙基。','undermine a wall/bank; be undermined by erosion','及物动词，字面指挖空或侵蚀某物的底部，使之可能倒塌。','墙基失去支撑后结构变得不稳。')],M('Changing the safety rules every day strengthened workers’ confidence and undermined nothing about the manager’s authority.','Changing the safety rules every day undermined workers’ confidence in the manager.','反复改规则会削弱信任，而非增强它。'),[Q(1,'What did the changing rules undermine?','Workers’ confidence in the manager','The wall’s stone foundation','The manager’s confidence grew stronger','Sense 1 means weaken trust or authority.','context'),Q(2,'How did water undermine the wall?','It washed soil from beneath the base.','It painted the wall’s surface.','It built a stronger foundation.','Sense 2 is literal erosion beneath a structure.','meaning'),Q(1,'Which phrase is common?','undermine confidence','undermine confidence by strengthening it','undermine to confidence','The verb commonly takes confidence, authority, or an effort as its object.','collocation'),Q(2,'Which use is literal rather than figurative?','Erosion undermines a riverbank.','Rumors undermine trust.','Delay undermines the campaign.','The first example describes physical removal of support below.','distinction')]);
P('underneath','Underneath comes from Old English underneoðan, combining under + a word meaning below; it can indicate a position below or covered by something, the lower side, or a hidden lower part.',[
C('underneath.s1','位置','The cat slept underneath the desk while the children finished their homework.','孩子们写作业时，猫睡在书桌下面。','underneath a table/blanket; hide underneath','介词或副词，表示在某物下面，常有遮盖关系。','猫位于书桌下方。'),C('underneath.s2','底面','The underside of the shelf was smooth, but underneath the paint there were old repair marks.','架子底面很光滑，但油漆下面有旧修补痕迹。','underneath of something; on the underneath','名词性或介词性用法，指某物的下侧或下面一面。','修补痕迹隐藏在表面油漆之下。'),C('underneath.s3','隐藏部分','Beneath her calm voice, there was anger underneath that she did not show to the audience.','她平静的声音之下藏着愤怒，只是没有在观众面前表现出来。','underneath the surface; underneath it all','名词或副词性用法，可指隐藏在表象下的部分或感受。','表面平静，但内心有未表达的愤怒。')],M('The cat slept underneath the desk, which means it rested on top of the desk’s upper surface.','The cat slept underneath the desk, below its top surface.','underneath表示在下方，不是置于物体顶面。'),[Q(1,'Where did the cat sleep?','Below the desk','On top of the desk','Inside a bridge foundation','Sense 1 is a location below something.','context'),Q(2,'Where were the repair marks?','Beneath the shelf’s paint on its lower side','On the shelf’s upper surface','In the cat’s blanket','Sense 2 refers to a lower side or covered surface.','meaning'),Q(3,'What was hidden underneath her calm voice?','Anger she did not show','A physical desk','A painted shelf','Sense 3 is the hidden part beneath an outward appearance.','meaning'),Q(3,'Which phrase uses the figurative sense?','underneath the surface, he was worried','underneath the table, the cat slept','underneath the shelf, the mark was visible','The first sentence points to an unexpressed inner feeling.','distinction')]);
P('undernutrition','Undernutrition combines under- + nutrition; nutrition comes from Latin nutrire “nourish.” It means an insufficient intake of calories or nutrients for health.',C('undernutrition.s1','营养与健康','The clinic screened children for undernutrition and arranged meals with enough protein and calories.','诊所为儿童筛查营养不足，并安排了含有足够蛋白质和热量的膳食。','child/maternal undernutrition; prevent undernutrition','不可数名词，指热量或营养摄入不足以维持健康。','筛查与营养餐用于应对摄入不足。'),M('The clinic diagnosed undernutrition even though the child received sufficient calories and all required nutrients every day.','The clinic diagnosed undernutrition after finding that the child lacked enough calories and nutrients.','每日摄入足够热量与营养不能支持undernutrition诊断。'),[Q(1,'What is undernutrition?','Insufficient calories or nutrients for health','Eating a balanced diet with enough nutrients','A hidden concern under a desk','The source definition is inadequate nutrient intake.','meaning'),Q(1,'What did the clinic arrange?','Meals with enough protein and calories','Meals with fewer nutrients','A legal hearing','The response addresses nutritional deficiency.','context'),Q(1,'Which phrase is natural?','screen for undernutrition','screen for undernutrition after confirming ideal nutrient intake','undernutrition the meal to the child','Clinics can screen people for undernutrition.','collocation'),Q(1,'What does nutrition refer to?','Nourishment from food and nutrients','A railway passage','An unchangeable rule','Under- means an insufficient amount of nourishment.','word-formation')]);
P('underpass','Underpass combines under + pass and names a passage running beneath a road or railway, or a road structure carrying traffic beneath another road.',[
C('underpass.s1','行人通道','Pedestrians used the underpass to cross beneath the busy railway without entering the tracks.','行人通过地下通道从繁忙铁路下方穿过，无须进入轨道区域。','pedestrian underpass; walk through an underpass','可数名词，指供人从道路或铁路下方通行的通道。','通道使行人安全地从铁轨下面穿过。'),C('underpass.s2','道路结构','The new underpass carried eastbound traffic beneath the main highway to reduce congestion at the junction.','新建下穿道路让向东车辆从主干道下方通行，以减少路口拥堵。','road underpass; build/pass through an underpass','可数名词，指让道路交通从另一条道路下方通过的结构。','车辆从主干道下面经过，避免平面交叉。')],M('Pedestrians crossed the railway in the underpass by walking along the active tracks above the tunnel.','Pedestrians crossed safely through the underpass beneath the railway tracks.','地下通道位于轨道下方，不能同时沿上方正在使用的轨道行走。'),[Q(1,'Why did pedestrians use the underpass?','To cross beneath the railway without entering the tracks','To walk along the active tracks','To cross over a bridge','Sense 1 is a passage for people below a road or railway.','context'),Q(2,'What did the road underpass carry?','Eastbound traffic beneath the highway','Pedestrians over the railway only','Water beneath a garden path','Sense 2 is a road structure carrying traffic below another road.','meaning'),Q(1,'Which phrase is natural?','pedestrian underpass','pedestrian underpass on top of the railway','underpass the road into traffic','A pedestrian underpass gives people a route below the road or track.','collocation'),Q(2,'What distinguishes the second sense?','It carries road traffic under another road.','It is only a tunnel for walkers beneath railway tracks.','It names an underground political group.','The road structure lets vehicles pass below a different roadway.','distinction')]);
P('underpin','Underpin combines under + pin; literally it means secure or support a structure from below, and figuratively it means form the base supporting an idea or system.',[
C('underpin.s1','建筑','Engineers installed steel supports to underpin the old wall before excavating beside its foundation.','工程师在墙基旁开挖前安装了钢支撑，从下方加固旧墙。','underpin a wall/foundation; underpinning work','及物动词，字面指从下面支撑建筑结构。','钢支撑承担墙体重量，防止地基受损。'),C('underpin.s2','理论基础','Reliable measurements underpin the team’s conclusion that the bridge can carry heavier traffic.','可靠测量数据支撑了团队关于桥梁能够承载更重交通的结论。','evidence/principles underpin a theory; underpin an argument','及物动词，比喻指构成观点、理论或系统的基础。','结论建立在测量数据之上。')],M('The conclusion was underpinned by no measurements or evidence, yet the report claimed that data formed its basis.','The conclusion was underpinned by measurements that supported the report’s reasoning.','没有测量数据就不能说数据支撑了结论。'),[Q(1,'Why did engineers underpin the wall?','To support it from below before excavation','To paint it above the foundation','To weaken its foundation','Sense 1 is physical support from underneath.','context'),Q(2,'What underpinned the bridge conclusion?','Reliable measurements','A lack of any evidence','A nearby underpass','Sense 2 is the figurative basis of an argument.','meaning'),Q(1,'Which phrase is natural?','underpin a foundation','underpin a foundation by removing all support','underpin into a wall','The verb can describe strengthening a wall from below.','collocation'),Q(2,'Which use is figurative?','Evidence underpins the theory.','Steel supports underpin the wall.','Workers underpin a building from below.','The first example means evidence forms the theory’s basis.','distinction')]);
P('underpopulated','Underpopulated is formed from under- + populated; populate comes from Latin populus “people.” It describes a place with a small population relative to its land or resources.',C('underpopulated.s1','人口分布','The northern province remained underpopulated despite its fertile land and newly built rail line.','尽管土地肥沃且新建了铁路，北部省份的人口仍然稀少。','underpopulated region/island; remain underpopulated','形容词，表示相对于土地面积或资源而言人口偏少。','广阔肥沃土地与较少居民形成对比。'),M('The island was underpopulated even though nearly every hectare held a dense city and millions of residents.','The island was underpopulated because it had vast open land and relatively few residents.','人口密集且有数百万居民与underpopulated相反。'),[Q(1,'What does underpopulated mean?','Having few people relative to the available land or resources','Having too many people for the land','Having no land at all','The adjective describes a relatively small population.','meaning'),Q(1,'Why was the northern province underpopulated?','It had vast fertile land but relatively few residents.','Every hectare held a dense city.','The rail line was underground.','The context compares available land with population size.','context'),Q(1,'Which phrase is natural?','an underpopulated island','an underpopulated island with millions on every hectare','underpopulated to the province','Underpopulated commonly describes a region, island, or area.','collocation'),Q(1,'What does populate contribute in the compound?','The number of people living in a place','A hidden reason','A building’s foundation','Under- indicates too few residents for the area or resources.','word-formation')]);
})(typeof window!=='undefined'?window:globalThis);
